import { NextResponse } from 'next/server';

export const revalidate = 86400; // refresh once per day

const TERMS: { term: string; definition: string; category: string }[] = [
  // ── Portfolio Theory ──────────────────────────────────────────────────────
  { term: 'Alpha', definition: 'Excess return generated relative to a benchmark index after adjusting for risk. An alpha of 1% means the portfolio outperformed by 1% beyond what its beta exposure predicts.', category: 'Portfolio Theory' },
  { term: 'Beta', definition: 'Measure of a security\'s systematic volatility relative to the market. A beta of 1.2 means the asset historically moves 20% more than the index in either direction.', category: 'Portfolio Theory' },
  { term: 'Sharpe Ratio', definition: 'Risk-adjusted return metric: (portfolio return − risk-free rate) ÷ standard deviation of returns. A ratio above 1.0 is generally considered acceptable; above 2.0 is excellent.', category: 'Portfolio Theory' },
  { term: 'Sortino Ratio', definition: 'A variant of the Sharpe Ratio that only penalises downside deviation rather than total volatility. Preferred when return distributions are asymmetric (e.g. strategies with positive skew).', category: 'Portfolio Theory' },
  { term: 'Calmar Ratio', definition: 'Annualised return divided by maximum drawdown. Favoured by CTA and systematic traders to evaluate return relative to worst-case loss. Higher is better.', category: 'Portfolio Theory' },
  { term: 'Information Ratio', definition: 'Active return divided by tracking error (active risk). Measures the consistency of an active manager\'s outperformance. A ratio above 0.5 is considered good; above 1.0 is exceptional.', category: 'Portfolio Theory' },
  { term: 'Treynor Ratio', definition: 'Excess return per unit of systematic risk (beta). Unlike Sharpe, which uses total volatility, Treynor divides active return by beta — relevant for well-diversified portfolios where idiosyncratic risk is negligible.', category: 'Portfolio Theory' },
  { term: 'R-Squared', definition: 'Proportion of a portfolio\'s return variance explained by benchmark movements. A high R-squared (near 1.0) means returns are largely explained by the index — signalling a "closet index fund."', category: 'Portfolio Theory' },
  { term: 'Tracking Error', definition: 'The standard deviation of the difference between portfolio returns and benchmark returns. Measures how closely a portfolio follows its benchmark. High tracking error = high active risk.', category: 'Portfolio Theory' },
  { term: 'Efficient Frontier', definition: 'The set of optimal portfolios offering the highest expected return for a given level of risk — derived from Markowitz\'s Modern Portfolio Theory. Points on the frontier are Pareto-optimal.', category: 'Portfolio Theory' },
  { term: 'CAPM', definition: 'Capital Asset Pricing Model: expected return = risk-free rate + beta × equity risk premium. The bedrock model linking systematic risk (beta) to required return and the foundation of much of modern finance.', category: 'Portfolio Theory' },
  { term: 'Correlation', definition: 'Ranges from −1 to +1 and measures how two assets move relative to each other. A correlation of 0 indicates independence; −1 means perfect inverse movement. Diversification exploits low or negative correlation.', category: 'Portfolio Theory' },
  { term: 'Covariance', definition: 'A statistical measure of how two assets move together. Positive covariance = same direction; negative = opposite. The building block of the portfolio variance calculation and correlation.', category: 'Portfolio Theory' },
  { term: 'Diversification', definition: 'The practice of spreading investments across uncorrelated assets to reduce idiosyncratic risk without sacrificing expected return. The only "free lunch" in finance, per Markowitz.', category: 'Portfolio Theory' },
  { term: 'Idiosyncratic Risk', definition: 'Company-specific risk that can be eliminated through diversification. Also called unsystematic risk. In a well-diversified portfolio, only systematic (market) risk remains.', category: 'Portfolio Theory' },
  { term: 'Systematic Risk', definition: 'Market-wide risk that cannot be diversified away — macroeconomic shocks, interest rate changes, geopolitical events. Compensated by the equity risk premium in the CAPM framework.', category: 'Portfolio Theory' },
  { term: 'Jensen\'s Alpha', definition: 'The intercept term in a regression of portfolio returns on market returns (CAPM). A positive Jensen\'s alpha indicates the manager generated returns beyond what CAPM predicts for the level of systematic risk taken.', category: 'Portfolio Theory' },
  { term: 'Active Share', definition: 'The percentage of a portfolio that differs from its benchmark. A 100% active share means no overlap; 0% is a pure index fund. High active share is a necessary (but not sufficient) condition for alpha generation.', category: 'Portfolio Theory' },
  { term: 'Omega Ratio', definition: 'The probability-weighted ratio of gains to losses above a threshold return. Unlike Sharpe, it captures the full return distribution rather than assuming normality — more relevant for hedge fund strategies with asymmetric payoffs.', category: 'Portfolio Theory' },
  { term: 'Portfolio Rebalancing', definition: 'Realigning portfolio weights to maintain a target allocation after market moves. Systematic rebalancing imposes a counter-trend discipline — buying underperformers and trimming outperformers.', category: 'Portfolio Theory' },
  { term: 'Kelly Criterion', definition: 'A formula determining the optimal fraction of capital to wager on a bet given its odds and edge: f* = (p·b − q) / b. Used in quantitative trading to size positions for maximum long-run geometric growth.', category: 'Portfolio Theory' },
  { term: 'Risk Parity', definition: 'A portfolio construction approach that allocates capital such that each asset contributes equally to portfolio risk, rather than equal dollar weights. Results in more bonds than equities in traditional implementations.', category: 'Portfolio Theory' },

  // ── Valuation ─────────────────────────────────────────────────────────────
  { term: 'Discounted Cash Flow', definition: 'A valuation method estimating the present value of expected future cash flows using a discount rate (WACC). The intrinsic value of an asset equals the sum of its discounted future cash flows plus terminal value.', category: 'Valuation' },
  { term: 'P/E Ratio', definition: 'Price-to-Earnings — the most common equity valuation multiple. Divides current share price by earnings per share. A high P/E implies the market expects strong future growth or lower risk.', category: 'Valuation' },
  { term: 'EV/EBITDA', definition: 'Enterprise Value divided by EBITDA. A capital-structure-neutral valuation multiple allowing comparison across companies with different debt levels. Typically ranges from 6–12x for mature businesses.', category: 'Valuation' },
  { term: 'WACC', definition: 'Weighted Average Cost of Capital — the blended required return on a firm\'s capital (equity + debt), weighted by their proportions. Used as the discount rate in DCF models.', category: 'Valuation' },
  { term: 'IRR', definition: 'Internal Rate of Return — the discount rate that makes the Net Present Value of all cash flows equal to zero. A project is attractive when its IRR exceeds the hurdle rate or cost of capital.', category: 'Valuation' },
  { term: 'Enterprise Value', definition: 'Market capitalisation plus total debt minus cash. Represents the theoretical acquisition cost of a business and is capital-structure-neutral, unlike market cap alone.', category: 'Valuation' },
  { term: 'Free Cash Flow', definition: 'Operating cash flow minus capital expenditures. Represents the cash a business generates after maintaining and expanding its asset base — the lifeblood of DCF models and a measure of true earnings power.', category: 'Valuation' },
  { term: 'Net Present Value', definition: 'Sum of all discounted future cash flows minus the initial investment. A positive NPV means the investment creates value at the given discount rate. The gold standard decision rule in corporate finance.', category: 'Valuation' },
  { term: 'EBITDA', definition: 'Earnings Before Interest, Taxes, Depreciation, and Amortization. A proxy for operating cash generation stripped of capital structure and accounting choices, widely used in LBO and M&A valuation.', category: 'Valuation' },
  { term: 'Terminal Value', definition: 'The present value of all cash flows beyond the explicit forecast horizon in a DCF. Typically 60–80% of total firm value — making it the most sensitive and debated component of any DCF model.', category: 'Valuation' },
  { term: 'Price-to-Book', definition: 'Market capitalisation divided by book value of equity. A ratio below 1.0 means the market values the firm below its accounting net worth. Central to value investing; Fama-French identified it as a return factor.', category: 'Valuation' },
  { term: 'Price-to-Sales', definition: 'Market cap divided by total revenue. Used for unprofitable growth companies where P/E is undefined. Compared across companies in the same industry to assess relative market sentiment.', category: 'Valuation' },
  { term: 'EV/Revenue', definition: 'Enterprise Value divided by trailing or forward revenue. Common in high-growth software and biotech where EBITDA is negative. Median SaaS multiples historically range from 5–15x.', category: 'Valuation' },
  { term: 'PEG Ratio', definition: 'P/E divided by the earnings growth rate. Developed by Peter Lynch as a growth-adjusted valuation metric. A PEG below 1.0 is typically considered undervalued relative to growth prospects.', category: 'Valuation' },
  { term: 'Dividend Discount Model', definition: 'Values a stock as the present value of all future dividends: P = D1 / (r − g). The simplest DCF variant, most applicable to mature dividend-paying companies with stable, predictable payouts.', category: 'Valuation' },
  { term: 'Comparable Company Analysis', definition: 'Valuing a company by comparing its trading multiples (EV/EBITDA, P/E, EV/Revenue) to a peer group of similar public companies. Reflects market-implied valuations rather than intrinsic value.', category: 'Valuation' },
  { term: 'Precedent Transaction Analysis', definition: 'Valuing a company by examining multiples paid in historical M&A transactions for comparable businesses. Typically yields higher multiples than comps analysis due to control premiums.', category: 'Valuation' },
  { term: 'Control Premium', definition: 'The premium above a company\'s market price paid in an acquisition, reflecting the value of controlling the business. Historically averages 20–40% above the undisturbed share price.', category: 'Valuation' },
  { term: 'Intrinsic Value', definition: 'The fundamental, "true" value of an asset based on expected cash flows and risk, independent of its current market price. The gap between intrinsic and market value is the margin of safety for value investors.', category: 'Valuation' },
  { term: 'Margin of Safety', definition: 'The discount to intrinsic value at which a value investor buys a security. Coined by Benjamin Graham, it provides a buffer against estimation errors. Buying at a 30–50% discount protects against downside surprises.', category: 'Valuation' },
  { term: 'Residual Income Model', definition: 'Values equity as book value plus the present value of future residual income (economic profit above the cost of equity). Useful when free cash flows are negative but earnings are positive.', category: 'Valuation' },
  { term: 'Sum-of-the-Parts', definition: 'A conglomerate valuation approach that values each business segment separately using appropriate multiples or DCFs, then sums the pieces. Often reveals a "conglomerate discount" when the sum exceeds the traded stock price.', category: 'Valuation' },

  // ── Fixed Income ──────────────────────────────────────────────────────────
  { term: 'Duration', definition: 'Sensitivity of a bond\'s price to a 1% change in interest rates, measured in years. A bond with duration of 5 will fall roughly 5% in price if rates rise 1%.', category: 'Fixed Income' },
  { term: 'Convexity', definition: 'The rate of change of duration as interest rates move. Positive convexity means price gains from rate drops exceed price losses from equivalent rate rises — a desirable property for bondholders.', category: 'Fixed Income' },
  { term: 'Yield Curve', definition: 'A line plotting interest rates on bonds of equal credit quality but differing maturities. Its shape (normal, flat, or inverted) is one of the most watched macro indicators in finance.', category: 'Fixed Income' },
  { term: 'Basis Points', definition: 'A unit equal to 1/100th of 1% (0.01%). Used to precisely communicate changes in interest rates, credit spreads, and yields. 50 basis points = 0.50%.', category: 'Fixed Income' },
  { term: 'Yield to Maturity', definition: 'The total annualised return an investor earns if they hold a bond to maturity and all coupon payments are reinvested at the same rate. The single most important bond pricing metric.', category: 'Fixed Income' },
  { term: 'Credit Spread', definition: 'The yield difference between a corporate bond and a risk-free government bond of the same maturity. Compensates investors for default risk; widens during recessions and credit stress events.', category: 'Fixed Income' },
  { term: 'Repo Rate', definition: 'Short for repurchase agreement rate. A borrower sells securities and agrees to repurchase them at a higher price. Repos are a primary funding mechanism for broker-dealers and the fixed income market.', category: 'Fixed Income' },
  { term: 'Coupon Rate', definition: 'The annual interest payment on a bond expressed as a percentage of face value. A bond with a $1,000 par value and 5% coupon pays $50 per year regardless of market price fluctuations.', category: 'Fixed Income' },
  { term: 'Par Value', definition: 'The face value of a bond — typically $1,000 — repaid to the holder at maturity. Bonds trade at a premium (above par) when coupon > market yield, and at a discount when coupon < market yield.', category: 'Fixed Income' },
  { term: 'Callable Bond', definition: 'A bond the issuer can redeem before maturity at a specified call price. Issuers exercise calls when rates fall (to refinance cheaper), so callable bonds carry reinvestment risk and offer higher yields as compensation.', category: 'Fixed Income' },
  { term: 'Convertible Bond', definition: 'A bond that can be converted into a predetermined number of equity shares at the holder\'s option. Offers downside protection of a bond with equity upside optionality — popular in growth company financing.', category: 'Fixed Income' },
  { term: 'High-Yield Bond', definition: 'Also called "junk bonds." Rated below BBB− by S&P or Baa3 by Moody\'s, reflecting higher default risk and thus higher yield. The high-yield market is a key funding source for leveraged buyouts.', category: 'Fixed Income' },
  { term: 'Investment Grade', definition: 'Bonds rated BBB− or above by S&P and Baa3 or above by Moody\'s. Considered relatively safe, they attract insurance companies, pension funds, and banks with regulatory capital constraints.', category: 'Fixed Income' },
  { term: 'CDO', definition: 'Collateralised Debt Obligation — a structured product that pools debt instruments and issues tranches with different risk/return profiles. CDOs backed by subprime mortgages were central to the 2008 financial crisis.', category: 'Fixed Income' },
  { term: 'MBS', definition: 'Mortgage-Backed Security — bonds backed by a pool of residential or commercial mortgages. Agency MBS (Fannie Mae, Freddie Mac) are considered near-sovereign; non-agency MBS carry credit risk.', category: 'Fixed Income' },
  { term: 'Spread Duration', definition: 'The sensitivity of a bond\'s price to a change in its credit spread, analogous to interest rate duration. A spread duration of 4 means a 100bps widening causes a ~4% price decline.', category: 'Fixed Income' },
  { term: 'Z-Spread', definition: 'The constant spread added to the entire risk-free spot curve to make the present value of a bond\'s cash flows equal to its market price. More precise than a simple yield spread because it accounts for the term structure.', category: 'Fixed Income' },
  { term: 'OAS', definition: 'Option-Adjusted Spread — the Z-spread adjusted for the value of embedded options (calls, puts, prepayment). Strips out the option component to give a clean measure of the credit and liquidity premium.', category: 'Fixed Income' },
  { term: 'Treasury Bill', definition: 'A short-term U.S. government obligation with maturities of 4, 8, 13, 17, 26, or 52 weeks, sold at a discount to face value. The closest approximation to a risk-free asset used in all financial models.', category: 'Fixed Income' },
  { term: 'TIPS', definition: 'Treasury Inflation-Protected Securities — U.S. government bonds whose principal adjusts with CPI inflation, ensuring the real value is preserved. The breakeven inflation rate is derived by comparing TIPS yields to nominal Treasury yields.', category: 'Fixed Income' },

  // ── Derivatives ───────────────────────────────────────────────────────────
  { term: 'Delta', definition: 'The rate of change in an option\'s price for a $1 move in the underlying asset. A delta of 0.60 means the option gains $0.60 for each $1 rise in the stock, and approximates the probability of expiring in-the-money.', category: 'Derivatives' },
  { term: 'Gamma', definition: 'The rate of change of delta per $1 move in the underlying. High gamma near expiry means delta can shift rapidly, creating large hedging costs for option sellers who must rebalance frequently.', category: 'Derivatives' },
  { term: 'Theta', definition: 'The daily rate of decline in an option\'s value due to the passage of time, all else equal. Option buyers face negative theta (time decay working against them); sellers earn theta as premium decay.', category: 'Derivatives' },
  { term: 'Vega', definition: 'Sensitivity of an option\'s price to a 1-percentage-point change in implied volatility. Long options have positive vega — they gain value if vol rises. Vol sellers (short vega) profit from volatility compression.', category: 'Derivatives' },
  { term: 'Rho', definition: 'Sensitivity of an option\'s price to a 1% change in risk-free interest rates. Long calls have positive rho; long puts have negative rho. Rho is largest for deep-in-the-money options with long maturities.', category: 'Derivatives' },
  { term: 'Implied Volatility', definition: 'The market\'s forward-looking expectation of how much an asset will move, extracted from option prices using a model like Black-Scholes. It is the key input priced in options and often used as a sentiment indicator.', category: 'Derivatives' },
  { term: 'VIX', definition: 'The CBOE Volatility Index — often called the "fear gauge." Measures the market\'s 30-day implied volatility expectation derived from S&P 500 options. Readings above 30 signal elevated fear and uncertainty.', category: 'Derivatives' },
  { term: 'Black-Scholes Model', definition: 'The landmark 1973 option pricing model by Black, Scholes, and Merton. Assumes log-normal returns, constant volatility, no dividends, and continuous hedging. The foundation of quantitative derivatives pricing despite its known limitations.', category: 'Derivatives' },
  { term: 'Put-Call Parity', definition: 'The no-arbitrage relationship: C − P = S − PV(K). A European call minus a put at the same strike equals the spot minus the discounted strike. Any violation creates a risk-free arbitrage opportunity.', category: 'Derivatives' },
  { term: 'Volatility Smile', definition: 'The observed pattern where implied volatility is higher for deep in-the-money and out-of-the-money options than at-the-money options, forming a U-shape. Contradicts Black-Scholes\' constant vol assumption and reflects fat tails.', category: 'Derivatives' },
  { term: 'Volatility Surface', definition: 'A 3D plot of implied volatility across strikes and maturities. Used by options traders to identify rich or cheap strikes and to hedge volatility exposure. Shape reveals market expectations of future vol dynamics.', category: 'Derivatives' },
  { term: 'Contango', definition: 'When futures prices are higher than the expected spot price — normal for commodities with storage costs. Investors rolling futures in contango pay a "roll cost" as they sell cheaper near-month and buy pricier far-month contracts.', category: 'Derivatives' },
  { term: 'Backwardation', definition: 'When futures prices are below the expected spot price, often when spot demand is high and supply is tight. Rolling long positions in backwardation generates positive roll yield — a structural tailwind.', category: 'Derivatives' },
  { term: 'Forward Contract', definition: 'A private, customisable agreement to buy or sell an asset at a specified price on a future date. Unlike standardised futures, forwards are OTC instruments and carry counterparty risk.', category: 'Derivatives' },
  { term: 'Futures Contract', definition: 'A standardised exchange-traded forward. Daily mark-to-market with margin requirements eliminates counterparty risk. Used for hedging commodities, currencies, equity indices, and interest rates.', category: 'Derivatives' },
  { term: 'Interest Rate Swap', definition: 'A contract exchanging fixed-rate for floating-rate interest payments on a notional principal. The most traded OTC derivative globally. Used to manage duration and interest rate exposure on balance sheets.', category: 'Derivatives' },
  { term: 'Credit Default Swap', definition: 'An insurance-like contract where the protection buyer pays periodic premiums; the seller pays face value if the reference entity defaults. CDS spreads are a real-time market-implied measure of credit risk.', category: 'Derivatives' },
  { term: 'Collar Strategy', definition: 'A protective options strategy combining a long put (downside protection) and a short call (caps upside) on an existing long stock position. Often implemented at near-zero net cost — the call premium funds the put.', category: 'Derivatives' },
  { term: 'Straddle', definition: 'Buying a call and a put at the same strike and expiry. Profits if the underlying moves significantly in either direction. A long straddle is a bet on realised volatility exceeding implied volatility.', category: 'Derivatives' },
  { term: 'Strangle', definition: 'Similar to a straddle but uses out-of-the-money options. Cheaper premium but requires a larger move to profit. Short strangles are a popular income strategy — collecting premium in low-volatility environments.', category: 'Derivatives' },
  { term: 'Iron Condor', definition: 'A neutral options strategy selling an OTM strangle while buying a wider strangle for protection. Profits when the underlying stays within a defined range. Maximum profit = net premium received.', category: 'Derivatives' },
  { term: 'Gamma Scalping', definition: 'Hedging a long gamma (long options) position by delta-hedging frequently as the underlying moves. The trader profits from the difference between realised and implied volatility, collecting gamma "dimes" through rebalancing.', category: 'Derivatives' },
  { term: 'Vanna', definition: 'The cross-Greek measuring how delta changes with implied volatility (or how vega changes with spot). Important for options books during vol spikes, when both spot and vol move simultaneously.', category: 'Derivatives' },
  { term: 'Term Structure of Volatility', definition: 'The pattern of implied volatility across different option maturities. A downward-sloping term structure (short-dated vol > long-dated) indicates near-term event uncertainty. Used in relative-value vol trading.', category: 'Derivatives' },

  // ── Quantitative ──────────────────────────────────────────────────────────
  { term: 'Z-Score', definition: 'The number of standard deviations a data point sits from the distribution mean. In quant finance, used to identify statistically significant price moves and to standardise factor signals for portfolio construction.', category: 'Quantitative' },
  { term: 'Mean Reversion', definition: 'The tendency for asset prices or spreads to revert toward their long-run historical average over time. Underpins pairs trading, statistical arbitrage, and many fixed income strategies.', category: 'Quantitative' },
  { term: 'Pairs Trading', definition: 'A market-neutral strategy that goes long one security and short a highly correlated one when their spread diverges. The bet is that the spread will revert; profit is independent of market direction.', category: 'Quantitative' },
  { term: 'Statistical Arbitrage', definition: 'Systematic exploitation of temporary mispricings identified through statistical models, relying on mean reversion across many positions. Differs from pure arbitrage — it carries statistical risk, not zero risk.', category: 'Quantitative' },
  { term: 'Cointegration', definition: 'A statistical property where two or more non-stationary time series move together in the long run, with their linear combination being stationary. The foundation of pairs trading — cointegrated pairs maintain a stable spread.', category: 'Quantitative' },
  { term: 'Autocorrelation', definition: 'The correlation of a time series with its own lagged values. Positive autocorrelation in returns indicates momentum; negative autocorrelation indicates mean reversion. Tests include the Ljung-Box and Durbin-Watson tests.', category: 'Quantitative' },
  { term: 'Backtesting', definition: 'Simulating a trading strategy on historical data to evaluate its performance. Subject to look-ahead bias, overfitting, and survivorship bias. A necessary but insufficient condition for strategy validation.', category: 'Quantitative' },
  { term: 'Sharpe-Optimal Portfolio', definition: 'The portfolio on the efficient frontier with the highest Sharpe Ratio — the tangency point between the capital market line and the efficient frontier. In equilibrium, this is the market portfolio.', category: 'Quantitative' },
  { term: 'Monte Carlo Simulation', definition: 'A computational technique generating thousands of random scenarios to estimate the probability distribution of outcomes. Used for option pricing, VaR estimation, retirement planning, and stress testing.', category: 'Quantitative' },
  { term: 'Principal Component Analysis', definition: 'A dimensionality reduction technique decomposing a dataset into uncorrelated principal components ordered by explained variance. The first three yield curve PCAs typically capture parallel shifts, slope, and curvature.', category: 'Quantitative' },
  { term: 'Regression to the Mean', definition: 'The statistical phenomenon whereby extreme observations tend to be followed by more average ones. Critical in finance — last year\'s best-performing fund is unlikely to be next year\'s winner for this very reason.', category: 'Quantitative' },
  { term: 'Overfitting', definition: 'When a model is too closely fitted to historical data, capturing noise rather than signal. An overfitted strategy shows excellent in-sample performance but degrades severely out-of-sample. The cardinal sin of quantitative finance.', category: 'Quantitative' },
  { term: 'Sharpe\'s Fundamental Law', definition: 'Information Coefficient × √Breadth ≈ Information Ratio. A manager\'s skill (IC) combined with the number of independent bets (breadth) determines achievable alpha. Diversifying bets is as important as individual stock selection skill.', category: 'Quantitative' },
  { term: 'Hidden Markov Model', definition: 'A statistical model where the system follows Markov transitions between unobserved states, generating observable outputs. Used in quantitative finance to identify market regimes (bull, bear, high-volatility) from price data.', category: 'Quantitative' },
  { term: 'Kalman Filter', definition: 'A recursive algorithm that estimates the state of a dynamic system from noisy measurements. Applied in finance for real-time estimation of hedge ratios, dynamic factor loadings, and spread trading signals.', category: 'Quantitative' },
  { term: 'Hurst Exponent', definition: 'A measure of long-term memory in a time series. H > 0.5 indicates trend persistence (momentum); H < 0.5 indicates mean reversion; H = 0.5 indicates a random walk. Used to select appropriate strategy type for a given asset.', category: 'Quantitative' },
  { term: 'Correlation Breakdown', definition: 'The empirically observed phenomenon where correlations across asset classes spike toward +1 during market crises, eliminating the diversification benefit precisely when it is most needed.', category: 'Quantitative' },
  { term: 'Ensemble Methods', definition: 'Machine learning approaches combining multiple models (e.g., Random Forest, gradient boosting) to improve prediction robustness. Increasingly used in alpha signal generation and credit risk modelling.', category: 'Quantitative' },
  { term: 'Cross-Sectional Momentum', definition: 'Ranking assets by past returns and going long winners while shorting losers. Distinct from time-series momentum (trend following) — it is relative performance that generates the signal, not absolute direction.', category: 'Quantitative' },
  { term: 'Signal Decay', definition: 'The rate at which a predictive alpha signal loses its forecasting power over time. High-frequency signals decay within milliseconds; fundamental value signals may persist for months. Understanding decay informs trading frequency and costs.', category: 'Quantitative' },

  // ── Risk Management ───────────────────────────────────────────────────────
  { term: 'Drawdown', definition: 'Peak-to-trough decline in portfolio value over a specific period. Maximum drawdown captures the worst such decline historically and is a key measure of downside risk for risk-averse investors.', category: 'Risk Management' },
  { term: 'Value at Risk (VaR)', definition: 'The maximum expected portfolio loss over a given time horizon at a specified confidence level. A 1-day 95% VaR of $1M means a 5% chance of losing more than $1M in a single day.', category: 'Risk Management' },
  { term: 'Expected Shortfall (CVaR)', definition: 'The expected loss given that the loss exceeds the VaR threshold. Also called Conditional VaR. More coherent than VaR because it captures the severity of tail losses, not just their frequency.', category: 'Risk Management' },
  { term: 'Stress Testing', definition: 'Applying extreme but plausible hypothetical scenarios (market crashes, rate shocks, geopolitical events) to a portfolio to assess potential losses. A regulatory requirement under Basel III and Dodd-Frank.', category: 'Risk Management' },
  { term: 'Volatility', definition: 'Statistical measure of the dispersion of returns, typically expressed as annualised standard deviation. Higher volatility implies greater uncertainty and is both a risk measure and the primary input to options pricing.', category: 'Risk Management' },
  { term: 'Skewness', definition: 'Measures asymmetry in the distribution of returns. Negative skew (left tail) means occasional large losses. Strategies that collect premium (options selling) typically exhibit negative skew — steady gains punctuated by blowups.', category: 'Risk Management' },
  { term: 'Kurtosis', definition: 'Measures the "fat-tailedness" of a return distribution. High excess kurtosis means extreme outcomes occur more often than a normal distribution predicts — a critical consideration for tail risk and VaR models.', category: 'Risk Management' },
  { term: 'Basis Risk', definition: 'The residual risk from an imperfect hedge — when the hedging instrument doesn\'t perfectly offset the position being hedged. Common in cross-hedging with futures or when correlations shift during stress.', category: 'Risk Management' },
  { term: 'Tail Risk', definition: 'The risk of rare but catastrophic outcomes in the tail of the return distribution. Often underpriced by models that assume normality. Investors pay a premium for tail protection in the form of crash puts or volatility strategies.', category: 'Risk Management' },
  { term: 'Liquidity Risk', definition: 'The risk that a position cannot be exited at a fair price within a reasonable timeframe. Assets can be asset-side illiquid (hard to sell) or funding-side illiquid (forced selling due to margin calls or redemptions).', category: 'Risk Management' },
  { term: 'Counterparty Risk', definition: 'The risk that the other party in a financial contract defaults before settlement. Central clearing houses (CCPs) and margin requirements exist to mitigate it. Central to the 2008 Lehman failure cascade.', category: 'Risk Management' },
  { term: 'Model Risk', definition: 'The risk that financial models are wrong or misused. Materialized in 2008 through CDO pricing models that underestimated correlation risk. Requires regular backtesting, stress testing, and model validation governance.', category: 'Risk Management' },
  { term: 'Concentration Risk', definition: 'Excessive exposure to a single security, sector, geography, or risk factor. A portfolio with 40% in one name has high concentration risk — a single adverse event can cause catastrophic losses.', category: 'Risk Management' },
  { term: 'Margin Call', definition: 'A demand from a broker that an investor deposits additional funds because a position has fallen below the maintenance margin requirement. Forced selling to meet margin calls can amplify market downturns.', category: 'Risk Management' },
  { term: 'Leverage Ratio', definition: 'Total assets divided by equity — measures financial leverage. Higher leverage amplifies both gains and losses. Basel III requires banks to maintain a minimum leverage ratio of 3% (Tier 1 capital / total exposure).', category: 'Risk Management' },

  // ── Factor Investing ──────────────────────────────────────────────────────
  { term: 'Momentum', definition: 'The tendency for assets with strong recent performance to continue outperforming over the near term. One of the most robust and persistent return factors documented in academic literature since Jegadeesh and Titman (1993).', category: 'Factor Investing' },
  { term: 'Value Factor', definition: 'The return premium earned by cheap stocks (low P/B, P/E) over expensive ones. Documented by Fama and French (1992). Has underperformed during growth-stock dominated bull markets but remains a foundational factor.', category: 'Factor Investing' },
  { term: 'Size Factor', definition: 'The historical tendency for small-cap stocks to outperform large-caps over the long run (the "small-firm effect"). Part of the Fama-French three-factor model. Has been debated since it appears to have weakened post-publication.', category: 'Factor Investing' },
  { term: 'Quality Factor', definition: 'A stock factor capturing companies with high profitability, stable earnings, low leverage, and strong accruals. High-quality firms are more defensive and exhibit superior risk-adjusted returns over full market cycles.', category: 'Factor Investing' },
  { term: 'Low Volatility Factor', definition: 'The empirical anomaly that lower-risk stocks deliver better risk-adjusted returns than high-risk stocks — a violation of CAPM\'s predicted positive risk-return relationship. Explained by leverage constraints and investor behaviour.', category: 'Factor Investing' },
  { term: 'Profitability Factor', definition: 'Added to the Fama-French model in 2015 — stocks with higher operating profitability earn higher future returns. Firms with high gross profit relative to assets systematically outperform their peers.', category: 'Factor Investing' },
  { term: 'Investment Factor', definition: 'Firms that invest conservatively (low asset growth) earn higher returns than aggressive investors. Part of the Fama-French five-factor model. Explained by the q-factor model as rational pricing of investment-related risk.', category: 'Factor Investing' },
  { term: 'Factor Crowding', definition: 'When too many investors allocate to the same factor, driving up valuations of factor-exposed stocks and reducing future expected returns. Crowded factors are vulnerable to sudden unwinds — as seen in the August 2007 quant crisis.', category: 'Factor Investing' },
  { term: 'Factor Timing', definition: 'Dynamically adjusting exposure to different factors based on their expected returns (valuations, macro cycle, spreads). Academically contentious — most evidence suggests factors are difficult to time reliably out-of-sample.', category: 'Factor Investing' },
  { term: 'Smart Beta', definition: 'Rules-based strategies systematically capturing factor premia (value, momentum, quality, low vol) through transparent, systematic rebalancing. A middle ground between passive index investing and active stock selection.', category: 'Factor Investing' },

  // ── Macro ─────────────────────────────────────────────────────────────────
  { term: 'Carry Trade', definition: 'Borrowing in a low-interest-rate currency and investing the proceeds in a higher-yielding currency or asset. Profitable in calm markets, but subject to sudden reversal ("carry unwind") during risk-off episodes.', category: 'Macro' },
  { term: 'Federal Funds Rate', definition: 'The target interest rate set by the FOMC at which U.S. banks lend excess reserves to each other overnight. The most important policy rate in the world — it anchors the entire dollar yield curve.', category: 'Macro' },
  { term: 'Quantitative Easing', definition: 'Central bank asset purchases (government bonds, MBS) that inject reserves into the banking system, lower long-term yields, and stimulate lending. Deployed at the zero lower bound when rate cuts are exhausted.', category: 'Macro' },
  { term: 'Inverted Yield Curve', definition: 'Occurs when short-term yields exceed long-term yields. Historically one of the most reliable recession predictors — the 2Y/10Y inversion preceded every U.S. recession since the 1970s.', category: 'Macro' },
  { term: 'Taylor Rule', definition: 'A formula prescribing central bank policy rates based on inflation deviation from target and the output gap: rate = r* + π + 0.5(π − π*) + 0.5(y − y*). A benchmark for evaluating whether monetary policy is loose or tight.', category: 'Macro' },
  { term: 'Phillips Curve', definition: 'The historical inverse relationship between unemployment and inflation. Appeared to break down in the 1970s stagflation and again in the 2010s when low unemployment failed to generate inflation — still debated by economists.', category: 'Macro' },
  { term: 'Output Gap', definition: 'The difference between actual GDP and potential GDP. A positive gap (overheating economy) typically precedes rate hikes; a negative gap (slack) enables easier monetary policy. Key input to the Taylor Rule.', category: 'Macro' },
  { term: 'Purchasing Power Parity', definition: 'The theory that exchange rates should adjust to equalise the price of identical goods across countries. In practice, currencies can deviate from PPP for decades due to capital flows, trade balances, and productivity differentials.', category: 'Macro' },
  { term: 'Uncovered Interest Rate Parity', definition: 'The theory that higher interest rate currencies should depreciate to offset their yield advantage. Empirically violated in the short run — the "forward premium puzzle" — which is what makes carry trades profitable.', category: 'Macro' },
  { term: 'Current Account', definition: 'Measures a country\'s trade in goods and services plus primary income flows (dividends, interest). A persistent deficit means a country imports more capital than it exports — the U.S. has run chronic deficits financed by global demand for dollar assets.', category: 'Macro' },
  { term: 'Fiscal Multiplier', definition: 'The change in GDP resulting from a unit increase in government spending. A multiplier above 1 means $1 of spending generates more than $1 of output. Highly contested — estimated to range from 0.5 to 2.5 depending on the cycle and monetary policy stance.', category: 'Macro' },
  { term: 'Sovereign Spread', definition: 'The yield premium demanded by investors to hold a government\'s debt over a risk-free benchmark. Reflects perceived fiscal sustainability, political risk, and currency risk. EM sovereign spreads are tracked via the EMBI index.', category: 'Macro' },
  { term: 'Stagflation', definition: 'A toxic combination of high inflation, high unemployment, and low growth. Contradicts the traditional Phillips Curve trade-off. The 1970s stagflation triggered by oil shocks forced a fundamental rethink of Keynesian economics.', category: 'Macro' },
  { term: 'Quantitative Tightening', definition: 'Central bank reduction of its balance sheet by allowing maturing bonds to roll off without reinvestment, or by outright sales. The reverse of QE — designed to drain liquidity and put upward pressure on long-term yields.', category: 'Macro' },
  { term: 'Debt-to-GDP', definition: 'Government debt as a percentage of annual economic output. A ratio above 90% was flagged by Reinhart-Rogoff as associated with lower growth (though their methodology was later contested). Japan\'s ratio exceeds 250%.', category: 'Macro' },
  { term: 'Dollar Milkshake Theory', definition: 'Brent Johnson\'s thesis that global debt denominated in dollars creates structural dollar demand: when liquidity tightens, EM countries must buy dollars to service debt, strengthening the greenback and triggering EM crises.', category: 'Macro' },
  { term: 'Petrodollar System', definition: 'The post-1973 arrangement where oil is priced and traded globally in U.S. dollars. Creates structural demand for dollar reserves globally and underpins dollar hegemony. A potential weakening point as BRICS nations diversify reserves.', category: 'Macro' },
  { term: 'Secular Stagnation', definition: 'Lawrence Summers\' hypothesis that advanced economies face a prolonged period of deficient aggregate demand, low real interest rates, and below-trend growth. Used to explain the post-2008 low-growth, low-inflation environment.', category: 'Macro' },
  { term: 'Velocity of Money', definition: 'The rate at which money circulates in the economy: V = GDP / M. A falling velocity means each dollar supports less economic activity. QE raised M2 but velocity collapsed — explaining why massive money printing failed to generate inflation initially.', category: 'Macro' },
  { term: 'Repo Market', definition: 'The short-term borrowing market where financial institutions exchange securities for cash overnight. The backbone of money market liquidity. The September 2019 repo spike (rates to 10%) revealed structural vulnerabilities in bank reserve management.', category: 'Macro' },

  // ── Capital Structure & Corporate Finance ──────────────────────────────────
  { term: 'Leverage', definition: 'The use of borrowed capital to amplify potential returns (and losses). Financial leverage is measured by debt-to-equity or debt-to-EBITDA ratios. Operating leverage measures fixed vs. variable cost sensitivity to revenue.', category: 'Corporate Finance' },
  { term: 'Modigliani-Miller Theorem', definition: 'In a perfect market (no taxes, no bankruptcy costs), capital structure is irrelevant to firm value. In reality, the tax shield on debt creates value, leading to an optimal debt level before financial distress costs outweigh tax benefits.', category: 'Corporate Finance' },
  { term: 'Dividend Policy', definition: 'Miller and Modigliani showed dividends are irrelevant in perfect markets — shareholders can create homemade dividends. In practice, dividends signal management confidence, attract income investors, and discipline capital allocation.', category: 'Corporate Finance' },
  { term: 'Share Buyback', definition: 'A company repurchasing its own shares from the market. Reduces shares outstanding, increasing EPS and often the share price. Can signal undervaluation, but critics argue it prioritises short-term share prices over long-term investment.', category: 'Corporate Finance' },
  { term: 'Debt Tax Shield', definition: 'The tax savings resulting from interest expense being deductible. Creates value proportional to the tax rate: Tax Shield = Debt × Tax Rate. A key incentive for corporate leverage and the basis of LBO economics.', category: 'Corporate Finance' },
  { term: 'Cost of Equity', definition: 'The return required by equity investors, estimated via CAPM or the dividend discount model. Used in WACC calculation. Unlike debt, it\'s not directly observable — it represents the opportunity cost of equity capital.', category: 'Corporate Finance' },
  { term: 'Accretion/Dilution Analysis', definition: 'In M&A, whether the acquisition increases (accretion) or decreases (dilution) the acquirer\'s EPS. Generally: stock deals above the target\'s P/E are dilutive; cash/debt deals can be accretive if the target\'s earnings yield exceeds the cost of debt.', category: 'Corporate Finance' },
  { term: 'Synergies', definition: 'Value created when two merging businesses are worth more together than apart — cost synergies (headcount, facilities), revenue synergies (cross-selling), or financial synergies (lower cost of capital). Acquirers often overpay for elusive synergies.', category: 'Corporate Finance' },
  { term: 'Goodwill', definition: 'The premium paid in an acquisition above fair market value of net identifiable assets. Represents brand, customer relationships, and synergies. Tested annually for impairment under GAAP/IFRS — large impairments signal overpayment.', category: 'Corporate Finance' },
  { term: 'Working Capital', definition: 'Current assets minus current liabilities. Measures short-term liquidity and operational efficiency. Negative working capital (e.g., Amazon, supermarkets) means suppliers finance operations — a competitive advantage.', category: 'Corporate Finance' },
  { term: 'ROIC', definition: 'Return on Invested Capital: NOPAT ÷ Invested Capital. The purest measure of how efficiently management deploys capital. A business creating value must generate ROIC above WACC — the spread is the economic profit margin.', category: 'Corporate Finance' },
  { term: 'Capital Allocation', definition: 'How management deploys the free cash flow generated by the business: reinvestment, acquisitions, dividends, buybacks, or debt repayment. The quality of capital allocation is the defining long-term driver of shareholder value.', category: 'Corporate Finance' },
  { term: 'LBO', definition: 'Leveraged Buyout — acquisition of a company financed primarily with debt, using the target\'s assets and cash flows as collateral. The private equity sponsor contributes 20–40% equity; returns are amplified by leverage and multiple expansion.', category: 'Corporate Finance' },
  { term: 'Mezzanine Finance', definition: 'A hybrid layer of capital between senior debt and equity in a capital structure — often subordinated debt with equity warrants. Expensive (12–20% return) but less dilutive than equity; used in LBOs and growth financings.', category: 'Corporate Finance' },
  { term: 'Covenant', definition: 'Contractual restriction in a debt agreement protecting lenders. Maintenance covenants (quarterly compliance tests) and incurrence covenants (triggered by actions). Violations give lenders the right to accelerate debt — a key risk in leveraged loans.', category: 'Corporate Finance' },

  // ── Trading & Markets ─────────────────────────────────────────────────────
  { term: 'Arbitrage', definition: 'Simultaneous purchase and sale of an asset in different markets to profit from a price discrepancy. Pure arbitrage is risk-free; in practice most "arbitrage" carries execution or basis risk.', category: 'Trading' },
  { term: 'Short Selling', definition: 'Borrowing shares and selling them, hoping to repurchase at a lower price and return to the lender. Profits from price declines. Involves unlimited theoretical downside risk and borrowing costs.', category: 'Trading' },
  { term: 'High-Frequency Trading', definition: 'Algorithmic trading executing thousands of orders per second using co-located servers. Profits from tiny price discrepancies and market microstructure. Reduces bid-ask spreads but raises concerns about market stability.', category: 'Trading' },
  { term: 'Dark Pool', definition: 'A private trading venue where large institutional orders are executed away from public exchanges to minimise market impact. Trades are reported post-execution. Account for ~15% of U.S. equity volume.', category: 'Trading' },
  { term: 'Mark to Market', definition: 'Valuing assets at their current market price rather than historical cost. Forces daily P&L recognition. Used in futures, derivatives, and hedge fund accounting. Can amplify losses in illiquid markets.', category: 'Trading' },
  { term: 'Bid-Ask Spread', definition: 'The difference between the highest price a buyer will pay (bid) and the lowest price a seller will accept (ask). A wider spread indicates lower liquidity or higher uncertainty. Market makers profit from this spread.', category: 'Trading' },
  { term: 'Market Impact', definition: 'The adverse price movement caused by executing a large order. Buying large quantities pushes prices up; selling pushes them down. Minimising market impact is the central challenge of institutional trading (execution alpha).', category: 'Trading' },
  { term: 'VWAP', definition: 'Volume-Weighted Average Price — a common benchmark for execution quality. Calculated as total dollar value traded divided by total shares. Large orders are often executed as VWAP strategies to minimise market impact.', category: 'Trading' },
  { term: 'TWAP', definition: 'Time-Weighted Average Price — executes an order evenly over a specified time period. Simpler than VWAP; chosen when volume patterns are unpredictable or when stealth is preferred to minimise signal leakage.', category: 'Trading' },
  { term: 'Slippage', definition: 'The difference between the expected trade price and the actual execution price. Caused by market impact, latency, and bid-ask spread. A critical but often underestimated cost in backtesting, especially for high-turnover strategies.', category: 'Trading' },
  { term: 'Order Book', definition: 'A real-time list of all buy and sell orders for a security, organised by price level. Depth of book analysis reveals supply/demand imbalances. Thin order books (little depth) indicate fragile, easily-moved markets.', category: 'Trading' },
  { term: 'Spoofing', definition: 'The illegal practice of placing large orders with no intent to execute to create a false impression of demand or supply, then cancelling before execution. Banned under the Dodd-Frank Act; increasingly prosecuted by the CFTC and DOJ.', category: 'Trading' },
  { term: 'Payment for Order Flow', definition: 'The practice of brokers routing customer orders to market makers in exchange for compensation. Controversial — Citadel Securities pays Robinhood hundreds of millions annually. Critics argue it creates a conflict with best execution obligations.', category: 'Trading' },
  { term: 'Prime Brokerage', definition: 'Services offered by major banks to hedge funds: stock lending for short selling, leverage provision, trade settlement, and risk reporting. Goldman Sachs and Morgan Stanley dominate the market.', category: 'Trading' },

  // ── Hedge Funds & Private Capital ─────────────────────────────────────────
  { term: 'Hedge Fund', definition: 'A lightly regulated investment pool using diverse strategies — long/short equity, global macro, arbitrage, credit, quant — targeting absolute returns regardless of market direction. Typically charges "2 and 20" (2% management fee, 20% performance fee).', category: 'Hedge Funds' },
  { term: 'Two and Twenty', definition: 'The traditional hedge fund fee structure: 2% annual management fee on AUM plus 20% performance fee on profits. Under pressure — average fees have declined to approximately "1.5 and 17" as institutional investors negotiate harder.', category: 'Hedge Funds' },
  { term: 'High Water Mark', definition: 'The highest NAV a fund has previously reached. The performance fee is only charged on new profits above this level — protecting investors from paying fees to recover from previous losses.', category: 'Hedge Funds' },
  { term: 'Hurdle Rate', definition: 'A minimum return threshold a fund must exceed before earning a performance fee. A 6% hurdle means the fund collects its 20% carry only on returns above 6%. Protects investors against paying fees for beta.', category: 'Hedge Funds' },
  { term: 'Long/Short Equity', definition: 'The most common hedge fund strategy: long undervalued stocks, short overvalued ones. Net exposure varies from net long to market neutral. The "classic" hedge fund approach pioneered by Alfred Winslow Jones in 1949.', category: 'Hedge Funds' },
  { term: 'Global Macro', definition: 'A top-down strategy making directional bets on currencies, rates, equities, and commodities based on macroeconomic analysis. George Soros famously broke the Bank of England in 1992 with a $10B macro short of the British pound.', category: 'Hedge Funds' },
  { term: 'Market Neutral', definition: 'A strategy maintaining zero or near-zero net market exposure by balancing longs and shorts. Returns are generated purely from security selection (alpha), insulated from broad market moves. Net beta ≈ 0.', category: 'Hedge Funds' },
  { term: 'Event-Driven', definition: 'Strategies exploiting corporate events: mergers, spinoffs, bankruptcies, restructurings. Merger arbitrage, distressed debt, and activist investing are all event-driven. Returns depend on event resolution, not market direction.', category: 'Hedge Funds' },
  { term: 'Private Equity', definition: 'Investing in companies not listed on public markets, primarily through leveraged buyouts, growth equity, or venture capital. PE firms hold assets for 5–7 years, aiming to create value through operational improvements and multiple expansion.', category: 'Private Capital' },
  { term: 'Venture Capital', definition: 'Early-stage equity investment in startups with high growth potential. Returns follow a power-law distribution — a small number of breakouts (Uber, Airbnb) generate most returns. Typical fund life: 10 years.', category: 'Private Capital' },
  { term: 'Carried Interest', definition: 'The share of profits (typically 20%) earned by private equity and hedge fund managers above the hurdle rate. Taxed at capital gains rates in most jurisdictions — a controversial tax treatment often targeted by reform proposals.', category: 'Private Capital' },
  { term: 'Dry Powder', definition: 'Committed but undeployed capital in private equity funds. During market downturns, dry powder becomes highly valuable as GPs can selectively deploy at attractive valuations. Global PE dry powder exceeded $3T post-2020.', category: 'Private Capital' },
  { term: 'J-Curve', definition: 'The typical private equity fund return profile: early negative returns from fees and initial write-downs, turning positive as portfolio companies mature and are exited. Early fund years often show a "J-shape" in the IRR profile.', category: 'Private Capital' },
  { term: 'MOIC', definition: 'Multiple on Invested Capital — total value received divided by total capital invested. A 3x MOIC means you received $3 for every $1 invested. Used alongside IRR; a 3x in 2 years is vastly different from a 3x in 8 years.', category: 'Private Capital' },
  { term: 'General Partner', definition: 'The fund manager in a private equity or hedge fund structure. The GP makes investment decisions, earns management fees and carried interest, and has unlimited liability (in theory). LPs provide capital; GP provides expertise.', category: 'Private Capital' },
  { term: 'Limited Partner', definition: 'An investor (pension fund, endowment, family office) that commits capital to a PE or VC fund. LPs have limited liability — they can only lose their invested capital. They receive distributions but have no management role.', category: 'Private Capital' },

  // ── Accounting & Financial Statements ────────────────────────────────────
  { term: 'Accrual Accounting', definition: 'Revenue and expenses are recognised when earned/incurred, not when cash is received or paid. Provides a more accurate picture of financial performance than cash accounting, but creates the possibility of earnings management.', category: 'Accounting' },
  { term: 'Earnings Per Share', definition: 'Net income attributable to common shareholders divided by weighted average diluted shares outstanding. The single most cited profitability metric in equity analysis. Diluted EPS includes the effect of options and convertibles.', category: 'Accounting' },
  { term: 'Revenue Recognition', definition: 'Under ASC 606/IFRS 15, revenue is recognised when performance obligations are satisfied — i.e., when control of goods or services transfers to the customer. Critical in evaluating SaaS (ratable), construction (percentage-of-completion), and licence deals.', category: 'Accounting' },
  { term: 'Goodwill Impairment', definition: 'A write-down of goodwill when its carrying value exceeds fair value. Triggered by deteriorating business performance or paying too much in an acquisition. Non-cash but signals strategic miscalculation by management.', category: 'Accounting' },
  { term: 'Deferred Revenue', definition: 'Cash received before the associated revenue is earned — a liability on the balance sheet. Common in subscription businesses (SaaS, media). Growing deferred revenue is a positive indicator of business momentum.', category: 'Accounting' },
  { term: 'Operating Leverage', definition: 'The degree to which fixed costs amplify earnings sensitivity to revenue changes. A business with high fixed costs and low variable costs has high operating leverage — small revenue gains produce disproportionately large profit swings.', category: 'Accounting' },
  { term: 'Accounts Receivable Days', definition: 'Measures how quickly a company collects payment: (Accounts Receivable ÷ Revenue) × 365. Rising DSO can indicate credit risk or aggressive revenue recognition. Comparing DSO trends against peers reveals collection efficiency.', category: 'Accounting' },
  { term: 'Inventory Turnover', definition: 'Cost of goods sold divided by average inventory. Measures how efficiently a company manages its stock. Low turnover may indicate obsolescence or weak demand; high turnover suggests efficient operations but potential stockout risk.', category: 'Accounting' },
  { term: 'GAAP vs IFRS', definition: 'The two dominant accounting frameworks. GAAP (U.S.) is rules-based with detailed guidance; IFRS (international) is principles-based with more judgement. Key differences: inventory (LIFO allowed in GAAP, banned in IFRS), goodwill, and lease accounting.', category: 'Accounting' },
  { term: 'Cash Conversion Cycle', definition: 'Days inventory outstanding + days sales outstanding − days payable outstanding. Measures how efficiently a company converts investments in inventory and other resources into cash. Negative CCC (e.g., Amazon) means suppliers finance operations.', category: 'Accounting' },

  // ── Behavioral Finance ────────────────────────────────────────────────────
  { term: 'Loss Aversion', definition: 'The empirical finding (Kahneman-Tversky) that losses hurt roughly 2x more than equivalent gains feel good. Leads to holding losers too long (avoiding realising the loss) and selling winners too early — the "disposition effect."', category: 'Behavioral Finance' },
  { term: 'Anchoring Bias', definition: 'Overreliance on the first piece of information encountered (the "anchor") when making decisions. Investors anchored to their purchase price often irrationally hold positions they would never initiate at current prices.', category: 'Behavioral Finance' },
  { term: 'Herding', definition: 'The tendency for investors to follow the crowd, abandoning independent analysis. Amplifies asset bubbles on the upside and panic selling on the downside. Responsible for momentum in prices and ultimately reversion to fundamentals.', category: 'Behavioral Finance' },
  { term: 'Overconfidence Bias', definition: 'The systematic tendency for investors to overestimate their skill and the precision of their forecasts. Studies show most active managers underperform benchmarks after fees, yet most believe they are above-average stock pickers.', category: 'Behavioral Finance' },
  { term: 'Recency Bias', definition: 'Overweighting recent events in forming expectations about the future. Investors who extrapolate strong recent market performance into the future tend to buy near market peaks — and flee near troughs.', category: 'Behavioral Finance' },
  { term: 'Confirmation Bias', definition: 'The tendency to seek and overweight information that confirms existing beliefs while dismissing contradicting evidence. Particularly dangerous in fundamental analysis — investors in love with a thesis ignore deteriorating fundamentals.', category: 'Behavioral Finance' },
  { term: 'Prospect Theory', definition: 'Kahneman and Tversky\'s framework describing how people actually make decisions under uncertainty — incorporating loss aversion, diminishing sensitivity, and probability weighting. Replaced expected utility theory as the standard descriptive model of choice.', category: 'Behavioral Finance' },
  { term: 'Mental Accounting', definition: 'The tendency to treat money differently based on its source or intended use, violating the fungibility of money. Investors who "never touch principal" or treat house money gains differently than earned income fall prey to this bias.', category: 'Behavioral Finance' },
  { term: 'Disposition Effect', definition: 'The documented tendency to sell winning positions too early and hold losing positions too long — driven by loss aversion and the desire to avoid realising losses. Has a measurable negative impact on portfolio performance.', category: 'Behavioral Finance' },
  { term: 'Narrative Economics', definition: 'Robert Shiller\'s framework arguing that viral economic narratives ("stories") drive economic events. Markets move on stories as much as fundamentals — understanding prevailing narratives is essential for macro investors.', category: 'Behavioral Finance' },

  // ── Technical Analysis ────────────────────────────────────────────────────
  { term: 'Support Level', definition: 'A price level where buying interest historically prevents a security from falling further. Support acts as a floor — if breached convincingly, former support often becomes resistance.', category: 'Technical Analysis' },
  { term: 'Resistance Level', definition: 'A price level where selling pressure historically prevents further advances. Psychologically significant round numbers often act as resistance. A breakout above resistance can signal a new trend.', category: 'Technical Analysis' },
  { term: 'Moving Average', definition: 'The average closing price over a specified period (e.g., 50-day, 200-day). Smooths out noise and highlights trend direction. The "golden cross" (50MA crossing above 200MA) is a bullish signal; "death cross" is bearish.', category: 'Technical Analysis' },
  { term: 'RSI', definition: 'Relative Strength Index — a momentum oscillator ranging 0–100, measuring the speed and magnitude of recent price changes. Readings above 70 suggest overbought conditions; below 30 suggest oversold. Developed by J. Welles Wilder in 1978.', category: 'Technical Analysis' },
  { term: 'MACD', definition: 'Moving Average Convergence Divergence — the difference between 12-day and 26-day EMA, with a 9-day signal line. Crossovers and divergences between MACD and price are interpreted as trend change signals.', category: 'Technical Analysis' },
  { term: 'Bollinger Bands', definition: 'Bands plotted two standard deviations above and below a 20-day moving average. Price touching the upper band signals potential overbought conditions; lower band signals oversold. Band width indicates volatility level.', category: 'Technical Analysis' },
  { term: 'Fibonacci Retracement', definition: 'Horizontal lines at key Fibonacci levels (23.6%, 38.2%, 61.8%) between a prior high and low, used to identify potential support/resistance levels during pullbacks. Widely watched but their predictive power is debated by academics.', category: 'Technical Analysis' },
  { term: 'Head and Shoulders', definition: 'A chart pattern with three peaks — a central peak (head) flanked by two lower peaks (shoulders). A bearish reversal pattern when the neckline is broken. The inverse head and shoulders is a bullish reversal pattern.', category: 'Technical Analysis' },
  { term: 'Volume Profile', definition: 'A histogram showing traded volume at each price level over a period. High-volume nodes indicate price levels with significant market interest (support/resistance). Low-volume areas tend to be traversed quickly.', category: 'Technical Analysis' },
  { term: 'On-Balance Volume', definition: 'A momentum indicator adding volume on up days and subtracting on down days. OBV diverging from price (rising OBV during falling prices) can signal accumulation by informed investors ahead of a price reversal.', category: 'Technical Analysis' },

  // ── Commodities ───────────────────────────────────────────────────────────
  { term: 'Commodity Supercycle', definition: 'A decades-long period of rising commodity prices driven by structural demand growth (e.g., industrialisation of China). Supercycles typically last 10–35 years; the debate on whether a new cycle began post-2020 is active in the investment community.', category: 'Commodities' },
  { term: 'Convenience Yield', definition: 'The implied benefit of holding physical inventory of a commodity over holding a futures contract. High convenience yield (basis for backwardation) reflects tight nearby supply and reluctance to part with physical stock.', category: 'Commodities' },
  { term: 'Roll Yield', definition: 'The profit or loss from rolling expiring futures contracts into the next month. Positive in backwardation (buy cheap far-month), negative in contango (buy expensive far-month). A structural drag for long commodity ETFs.', category: 'Commodities' },
  { term: 'WTI vs Brent', definition: 'The two dominant oil benchmarks. WTI (West Texas Intermediate) is a U.S. crude benchmark; Brent is the global benchmark for ~70% of oil contracts. Their spread reflects transportation costs, trade flows, and regional supply dynamics.', category: 'Commodities' },
  { term: 'Crack Spread', definition: 'The price differential between crude oil and petroleum products (gasoline, diesel). A proxy for refining margins. Widens when refined product demand is strong relative to crude input costs — a key metric for integrated oil companies.', category: 'Commodities' },
  { term: 'Gold-Silver Ratio', definition: 'The price of gold divided by the price of silver. Historically averages around 60–70:1. An extreme ratio (>80) has historically preceded silver outperformance. Used as a relative-value indicator between the two metals.', category: 'Commodities' },

  // ── Digital Assets & Fintech ───────────────────────────────────────────────
  { term: 'Bitcoin Halving', definition: 'Approximately every 4 years, the Bitcoin block reward halves, reducing the rate of new supply. Supply shocks historically precede bull markets as new issuance falls. The supply schedule makes Bitcoin\'s total cap fixed at 21 million coins.', category: 'Digital Assets' },
  { term: 'Proof of Work', definition: 'Bitcoin\'s consensus mechanism where miners compete to solve computationally expensive puzzles. Energy-intensive but provides immutable, decentralised security. Satoshi Nakamoto chose PoW as the "one-CPU-one-vote" anti-sybil mechanism.', category: 'Digital Assets' },
  { term: 'Proof of Stake', definition: 'A consensus mechanism where validators stake cryptocurrency as collateral to validate transactions. More energy-efficient than PoW. Ethereum transitioned to PoS in "The Merge" (September 2022), reducing energy consumption by ~99.95%.', category: 'Digital Assets' },
  { term: 'DeFi', definition: 'Decentralised Finance — financial services (lending, trading, derivatives) built on public blockchains, primarily Ethereum. Governed by smart contracts rather than intermediaries. TVL peaked at ~$180B in 2021, collapsed in the 2022 crypto bear market.', category: 'Digital Assets' },
  { term: 'Stablecoin', definition: 'A cryptocurrency designed to maintain a peg to a fiat currency. Fiat-backed (USDC, Tether), crypto-backed (DAI), or algorithmic (TerraUSD, which collapsed in May 2022). Crucial for DeFi liquidity and crypto trading.', category: 'Digital Assets' },
  { term: 'On-Chain Analytics', definition: 'Analysis of publicly available blockchain data to infer investor behaviour — HODLer distribution, whale movements, exchange flows, SOPR. Provides a "glass box" view of network activity not available for traditional assets.', category: 'Digital Assets' },
  { term: 'Tokenomics', definition: 'The economic design of a cryptocurrency or token: issuance schedule, distribution, utility, governance rights, and incentive mechanisms. Well-designed tokenomics align incentives; poorly designed ones lead to hyperinflation or death spirals.', category: 'Digital Assets' },

  // ── Real Estate ───────────────────────────────────────────────────────────
  { term: 'Cap Rate', definition: 'Capitalisation Rate: NOI ÷ Property Value. The unlevered yield on a real estate investment. A lower cap rate implies higher valuations (more demand) or lower perceived risk. Office cap rates expanded sharply post-COVID.', category: 'Real Estate' },
  { term: 'Net Operating Income', definition: 'Property revenue minus operating expenses (excluding financing). The numerator in cap rate calculations. Rising NOI through rent growth or cost reduction directly increases property value.', category: 'Real Estate' },
  { term: 'REIT', definition: 'Real Estate Investment Trust — a company owning income-producing real estate that distributes at least 90% of taxable income to shareholders as dividends. Provides liquid, diversified real estate exposure without direct ownership.', category: 'Real Estate' },
  { term: 'Loan-to-Value', definition: 'Mortgage debt divided by property value. A key underwriting metric; most lenders cap commercial real estate LTV at 65–75%. Rising rates reduced property values in 2022–23, pushing LTVs above covenant thresholds.', category: 'Real Estate' },
  { term: 'Debt Service Coverage Ratio', definition: 'Net Operating Income divided by annual debt service (principal + interest). A DSCR below 1.0 means the property doesn\'t generate enough income to cover its debt. Most lenders require minimum DSCR of 1.25x.', category: 'Real Estate' },

  // ── Banking & Regulation ──────────────────────────────────────────────────
  { term: 'Basel III', definition: 'Post-crisis bank capital regulation requiring minimum CET1 capital ratios of 4.5%, a capital conservation buffer of 2.5%, and a leverage ratio of 3%. Introduced liquidity coverage ratio (LCR) and net stable funding ratio (NSFR).', category: 'Banking' },
  { term: 'Tier 1 Capital', definition: 'The highest-quality bank capital: common equity plus retained earnings. The primary cushion absorbing losses before insolvency. A bank\'s Tier 1 ratio measures its financial health; regulators require minimum 6% under Basel III.', category: 'Banking' },
  { term: 'Net Interest Margin', definition: 'The difference between a bank\'s interest income on loans and payments on deposits, expressed as a percentage of assets. A key profitability metric for banks — NIM compresses when the yield curve flattens or inverts.', category: 'Banking' },
  { term: 'Fractional Reserve Banking', definition: 'Banks lend out most deposits, keeping only a fraction in reserve. Creates money through the "money multiplier" effect. The reserve requirement in the U.S. was set to zero in 2020; banks are now constrained by capital, not reserves.', category: 'Banking' },
  { term: 'Too Big to Fail', definition: 'The implicit government guarantee that large, systemically important financial institutions (SIFIs) will be rescued in a crisis to prevent contagion. Creates moral hazard — institutions take excessive risk knowing losses will be socialised.', category: 'Banking' },
  { term: 'Stress Test', definition: 'Regulatory exercise (DFAST, CCAR in the U.S.) simulating severe adverse economic scenarios to verify banks hold sufficient capital. Annual results affect dividend and buyback approvals. Introduced post-2008 to prevent systemic failure.', category: 'Banking' },
  { term: 'Glass-Steagall Act', definition: 'The 1933 law separating commercial banking from investment banking. Repealed in 1999 by Gramm-Leach-Bliley, allowing universal banking models. Many argue repeal contributed to 2008 crisis risk-taking; reinstatement is periodically proposed.', category: 'Banking' },
  { term: 'Dodd-Frank Act', definition: 'The 2010 U.S. financial reform law enacted after the 2008 crisis. Created the CFPB, mandated central clearing of derivatives, required bank stress testing, and introduced the Volcker Rule banning proprietary trading at deposit-taking banks.', category: 'Banking' },

  // ── Economic Indicators ───────────────────────────────────────────────────
  { term: 'PMI', definition: 'Purchasing Managers\' Index — a survey-based leading indicator of economic activity. Above 50 indicates expansion; below 50 signals contraction. Manufacturing and Services PMIs are released monthly and closely watched by central banks.', category: 'Economic Indicators' },
  { term: 'Consumer Price Index', definition: 'Measures the weighted average price of a basket of consumer goods and services. The primary inflation gauge used by the Federal Reserve. Core CPI (excluding food and energy) strips out volatile components for a cleaner underlying trend.', category: 'Economic Indicators' },
  { term: 'PCE Deflator', definition: 'The Fed\'s preferred inflation measure — Personal Consumption Expenditure Price Index. Unlike CPI, PCE adjusts for substitution effects (consumers switch to cheaper goods) and has a broader coverage of expenditures.', category: 'Economic Indicators' },
  { term: 'Non-Farm Payrolls', definition: 'Monthly U.S. employment report from the Bureau of Labor Statistics, covering non-agricultural jobs. The single most market-moving economic data release. Large beats/misses relative to consensus cause immediate repricing of rate expectations.', category: 'Economic Indicators' },
  { term: 'ISM Manufacturing', definition: 'The monthly survey of purchasing managers in manufacturing — a leading indicator of industrial activity. A reading above 50 indicates expansion. New orders sub-index is particularly forward-looking and market-sensitive.', category: 'Economic Indicators' },
  { term: 'JOLTS Report', definition: 'Job Openings and Labor Turnover Survey — tracks job openings, hires, and separations. The quits rate is a leading indicator of wage inflation (workers only quit when confident of better opportunities). Became closely watched post-2021.', category: 'Economic Indicators' },
  { term: 'Conference Board LEI', definition: 'Leading Economic Index — a composite of 10 forward-looking indicators (yield curve, ISM new orders, building permits). Declining LEI over 6 months is a historical recession signal. Fell sharply throughout 2022–23 amid rate hike cycle.', category: 'Economic Indicators' },
  { term: 'NAHB Housing Market Index', definition: 'A monthly survey of home builders assessing current sales, expected sales, and buyer traffic. A leading indicator of residential construction and housing demand. Collapsed in 2022 as mortgage rates spiked to 7%+.', category: 'Economic Indicators' },

  // ── International Finance ─────────────────────────────────────────────────
  { term: 'Foreign Exchange Reserve', definition: 'Foreign currency assets held by a central bank, primarily U.S. dollars, euros, gold, and IMF Special Drawing Rights. Used to defend the exchange rate, service foreign debt, and signal confidence. China holds the world\'s largest reserves at ~$3.2T.', category: 'International Finance' },
  { term: 'SDR', definition: 'Special Drawing Rights — an international reserve asset created by the IMF. Its value is based on a basket of five currencies (USD, EUR, CNY, JPY, GBP). SDRs can be exchanged between member countries to supplement reserves.', category: 'International Finance' },
  { term: 'Brady Bonds', definition: 'Dollar-denominated bonds issued by developing countries in the 1980s–90s to restructure bank debt. Named after Treasury Secretary Nicholas Brady. Collateralised by U.S. zero-coupon Treasuries, they created the modern EM bond market.', category: 'International Finance' },
  { term: 'Currency Peg', definition: 'A fixed exchange rate system where a country ties its currency to another (usually the USD). Provides exchange rate stability but requires large reserves and constrains monetary policy. Hong Kong\'s peg to the USD has held since 1983.', category: 'International Finance' },
  { term: 'Eurodollar', definition: 'U.S. dollar deposits held in banks outside the United States. Not subject to Federal Reserve regulation. The Eurodollar market is enormous ($10T+) and is the primary pricing reference for short-term dollar funding rates (SOFR, formerly LIBOR).', category: 'International Finance' },

  // ── ESG & Sustainability ───────────────────────────────────────────────────
  { term: 'ESG', definition: 'Environmental, Social, and Governance — non-financial factors increasingly integrated into investment analysis and capital allocation decisions. Contested in both academic (mixed evidence on returns) and political spheres.', category: 'ESG' },
  { term: 'Carbon Credits', definition: 'Tradeable permits representing the right to emit one tonne of CO2. Cap-and-trade systems (EU ETS) allocate credits and allow companies to buy/sell them, creating a market price for carbon. Pricing carbon correctly is crucial for decarbonisation incentives.', category: 'ESG' },
  { term: 'SFDR', definition: 'Sustainable Finance Disclosure Regulation — EU framework classifying investment funds by sustainability credentials. Article 6 (no sustainability claims), Article 8 (ESG characteristics), Article 9 (sustainable investment objective). Reshaping European asset management.', category: 'ESG' },
  { term: 'Net Zero', definition: 'A state where greenhouse gas emissions are balanced by carbon removal. The Paris Agreement\'s 1.5°C target requires global net zero by 2050. Major asset managers and corporates are committing to net zero portfolios, impacting capital allocation to carbon-intensive sectors.', category: 'ESG' },
  { term: 'Greenwashing', definition: 'Misleading claims about the environmental credentials of products, investments, or corporate practices. Increasingly scrutinised by regulators (SEC, EU) as ESG fund assets swelled. Several fund managers have been investigated for overstating sustainability credentials.', category: 'ESG' },

  // ── Portfolio Theory (extended) ────────────────────────────────────────────
  { term: 'Black-Litterman Model', definition: 'A portfolio optimization framework that combines market-implied equilibrium returns with investor views. Addresses the sensitivity problem of mean-variance optimization by anchoring to the market portfolio and adjusting for conviction-weighted views.', category: 'Portfolio Theory' },
  { term: 'Maximum Drawdown', definition: 'The peak-to-trough percentage decline in a portfolio\'s value over a given period. A key risk metric for understanding worst-case loss scenarios. A drawdown of -30% requires a subsequent +43% gain just to break even.', category: 'Portfolio Theory' },
  { term: 'Ulcer Index', definition: 'A measure of drawdown-based risk that captures the depth and duration of price declines. Unlike standard deviation, it only penalizes downside volatility. Lower is better; funds with low Ulcer Index experience less sustained drawdown pain.', category: 'Portfolio Theory' },
  { term: 'Conditional Value at Risk', definition: 'Also called Expected Shortfall — the expected loss given that the loss exceeds the VaR threshold. If 1-day 99% CVaR is $1M, the average loss on the worst 1% of days is $1M. Preferred over VaR for capturing tail risk.', category: 'Portfolio Theory' },
  { term: 'Shrinkage Estimator', definition: 'A technique that "shrinks" sample covariance estimates toward a structured target (often identity matrix) to reduce estimation error. Ledoit-Wolf shrinkage is widely used in portfolio construction to produce more stable covariance matrices.', category: 'Portfolio Theory' },
  { term: 'Factor Exposure', definition: 'The degree to which a portfolio\'s return is driven by a specific systematic risk factor (value, momentum, quality, low volatility). Measuring factor exposures allows attribution of returns and avoids unintended concentrated bets.', category: 'Portfolio Theory' },
  { term: 'Portable Alpha', definition: 'A strategy that separates alpha generation from beta exposure. Investors obtain cheap beta via derivatives (S&P 500 futures) and overlay alpha from an uncorrelated active strategy. Enables pure skill-based return stacking.', category: 'Portfolio Theory' },
  { term: 'Tail Risk Hedging', definition: 'Using out-of-the-money put options, variance swaps, or other instruments to protect against extreme market dislocations. The "insurance premium" costs drag in normal markets but provides critical protection during crises like 2008 or March 2020.', category: 'Portfolio Theory' },

  // ── Valuation (extended) ───────────────────────────────────────────────────
  { term: 'Sum-of-the-Parts Valuation', definition: 'Valuing each business segment or asset independently and summing them. Common for conglomerates where the market applies a discount to the blended multiple. Activist investors often argue the parts are worth more than the whole.', category: 'Valuation' },
  { term: 'Replacement Cost Valuation', definition: 'Estimating a company\'s value based on the cost to recreate its assets. Relevant for capital-intensive businesses (infrastructure, real estate). A Tobin\'s Q below 1.0 signals the market values the firm below its replacement cost.', category: 'Valuation' },
  { term: 'Residual Income Model', definition: 'Values equity as book value plus the present value of future residual income (net income minus equity charge). Residual income = earnings − (cost of equity × equity book value). Useful when cash flows are hard to estimate but earnings are stable.', category: 'Valuation' },
  { term: 'Gordon Growth Model', definition: 'Values a stock as D₁ / (r − g): next dividend divided by the difference between required return and perpetual growth rate. A special case of DCF for steady-state dividend payers. Highly sensitive to assumptions about terminal growth rate.', category: 'Valuation' },
  { term: 'LBO Valuation', definition: 'Values a company from a private equity buyer\'s perspective — how much can be paid given a target IRR and expected exit multiple, constrained by debt capacity. Produces a "floor" valuation anchored by leverage and cash flow generation.', category: 'Valuation' },
  { term: 'EV/EBIT', definition: 'Enterprise value divided by earnings before interest and taxes. Unlike EBITDA-based multiples, it captures D&A expense — more conservative for capital-intensive businesses where depreciation reflects real economic cost.', category: 'Valuation' },
  { term: 'Price/Book Ratio', definition: 'Market capitalisation divided by shareholders\' equity. A P/B below 1.0 implies the market values the firm below its accounting net assets — common in banking crises, value traps, or declining industries. Warren Buffett famously used P/B as a Berkshire buyback trigger.', category: 'Valuation' },
  { term: 'Reverse DCF', definition: 'Instead of projecting cash flows to derive a price target, start with the current stock price and solve for the implied growth rate the market is pricing in. If the implied growth rate exceeds what\'s realistic, the stock is overvalued.', category: 'Valuation' },
  { term: 'Football Field Chart', definition: 'A summary valuation graphic showing the range of values produced by different methods (DCF, comps, precedent transactions, LBO). Allows quick comparison of valuation floors and ceilings across methodologies — standard in investment banking pitchbooks.', category: 'Valuation' },

  // ── Fixed Income (extended) ────────────────────────────────────────────────
  { term: 'Z-Spread', definition: 'Zero-volatility spread — the constant spread added to the entire risk-free spot curve to make the present value of a bond\'s cash flows equal to its market price. Accounts for term structure shape; more precise than nominal spread for non-benchmark bonds.', category: 'Fixed Income' },
  { term: 'OAS', definition: 'Option-Adjusted Spread — the spread over the risk-free curve after removing the value of embedded options (calls, puts, prepayments). The "true" credit spread for callable bonds and MBS. A higher OAS means more compensation per unit of credit risk.', category: 'Fixed Income' },
  { term: 'G-Spread', definition: 'The yield spread of a bond over the interpolated government (on-the-run) yield of the same maturity. The simplest measure of credit risk premium. Does not adjust for the shape of the yield curve or embedded options.', category: 'Fixed Income' },
  { term: 'Asset Swap Spread', definition: 'The spread paid above LIBOR/SOFR when converting a fixed-coupon bond into floating using an interest rate swap. Represents the all-in credit premium net of interest rate risk. Widely used to compare relative value across fixed income instruments.', category: 'Fixed Income' },
  { term: 'Negative Convexity', definition: 'When a bond\'s price appreciation slows as yields fall — the opposite of the typical bond behaviour. Occurs with callable bonds and mortgage-backed securities because the issuer/borrower prepays when rates drop, capping price upside for investors.', category: 'Fixed Income' },
  { term: 'Reinvestment Risk', definition: 'The risk that future coupon payments will be reinvested at a lower rate than the YTM assumed at purchase. Duration measures price risk; reinvestment risk is the offsetting concern for long-term bond holders seeking to lock in a return.', category: 'Fixed Income' },
  { term: 'Basis Point Value', definition: 'The change in a bond\'s price for a 1 basis point (0.01%) move in yield. Also called DV01 (dollar value of one basis point). Fundamental to interest rate risk hedging — a $10M 10-year Treasury at 4.5% has a DV01 around $8,300.', category: 'Fixed Income' },
  { term: 'Repo Rate', definition: 'The interest rate in a repurchase agreement (repo) — essentially a collateralised short-term loan. Securities (usually Treasuries) are sold with an agreement to buy back at a higher price. The difference is the repo rate. Fundamental to bank funding and the short end of the yield curve.', category: 'Fixed Income' },
  { term: 'Treasury Inflation-Protected Securities', definition: 'TIPS — U.S. government bonds whose principal adjusts with CPI. The coupon is fixed but applied to the inflation-adjusted principal, so real purchasing power is preserved. Break-even inflation rate = nominal yield − TIPS yield.', category: 'Fixed Income' },
  { term: 'Fallen Angel', definition: 'A corporate bond originally issued with investment-grade credit rating that has since been downgraded to high-yield/junk status. Forced selling by investment-grade-only mandates creates temporary dislocations — a strategy exploited by distressed debt funds.', category: 'Fixed Income' },

  // ── Derivatives (extended) ─────────────────────────────────────────────────
  { term: 'Bull Call Spread', definition: 'An options strategy: buy a call at strike K₁ and sell a call at higher strike K₂. Reduces premium cost relative to a long call but caps upside above K₂. Profits if the underlying rises moderately above K₁.', category: 'Derivatives' },
  { term: 'Iron Condor', definition: 'A range-bound options strategy combining a bull put spread and a bear call spread. Profits when the underlying trades within a defined band. Popular in low-volatility environments where the trader sells rich implied volatility.', category: 'Derivatives' },
  { term: 'Straddle', definition: 'Buying a call and a put at the same strike and expiry. Profits from a large move in either direction. The break-even points are strike ± total premium paid. Used to bet on volatility without a directional view.', category: 'Derivatives' },
  { term: 'Strangle', definition: 'Like a straddle but using out-of-the-money options — a lower-strike put and a higher-strike call. Cheaper than a straddle but requires a larger move to profit. Common pre-earnings or pre-event when a big move is expected.', category: 'Derivatives' },
  { term: 'Gamma Squeeze', definition: 'When rising stock prices force market makers who are short calls to buy stock to maintain delta neutrality, driving prices higher in a feedback loop. The 2021 GameStop episode was partly a gamma squeeze driven by coordinated retail options buying.', category: 'Derivatives' },
  { term: 'Synthetic Long', definition: 'Replicating a long stock position using options: buy a call and sell a put at the same strike and expiry. Economics are similar to owning the stock but require only the net premium and can be constructed with leverage.', category: 'Derivatives' },
  { term: 'Calendar Spread', definition: 'Selling a near-term option and buying a longer-dated option at the same strike. Profits from time decay differential (theta) and rising implied volatility. The ideal outcome is the underlying expiring at the short strike on the near-dated expiry.', category: 'Derivatives' },
  { term: 'Risk Reversal', definition: 'Simultaneously selling an OTM put and buying an OTM call (or vice versa). Zero-cost or low-cost directional bet. The skew of risk reversals (25-delta RR) in FX is a key gauge of market sentiment and hedging demand.', category: 'Derivatives' },
  { term: 'Forward Rate Agreement', definition: 'An OTC contract that locks in an interest rate for a future borrowing period. If the actual rate exceeds the agreed rate at settlement, the seller pays the difference. Used by corporates and banks to hedge short-term interest rate exposure.', category: 'Derivatives' },
  { term: 'Convertible Bond Arbitrage', definition: 'A hedge fund strategy that buys convertible bonds and shorts the underlying equity to isolate the embedded cheap optionality and credit spread, hedging away the delta. Profits from mispricing in the volatility or credit components.', category: 'Derivatives' },

  // ── Quantitative Finance (extended) ───────────────────────────────────────
  { term: 'Ornstein-Uhlenbeck Process', definition: 'A mean-reverting stochastic process widely used to model interest rates (Vasicek model), spreads, and volatility. Unlike a random walk, it has a pull toward a long-run mean with a speed of mean reversion parameter. Foundational in pairs trading strategies.', category: 'Quantitative' },
  { term: 'Brownian Motion', definition: 'Also called Wiener Process — a continuous-time stochastic process where increments are independent, normally distributed, and have zero mean. The fundamental building block of most derivatives pricing models including Black-Scholes.', category: 'Quantitative' },
  { term: 'Ito\'s Lemma', definition: 'The stochastic calculus chain rule for functions of Brownian motion. Adds a convexity (second-order) term absent in ordinary calculus. Used to derive the Black-Scholes PDE and any derivatives pricing result involving geometric Brownian motion.', category: 'Quantitative' },
  { term: 'Monte Carlo Simulation', definition: 'A numerical technique using thousands of randomly generated scenarios to price complex derivatives, estimate portfolio risk, or project retirement outcomes. Essential when analytical closed-form solutions don\'t exist — path-dependent options, CLOs, multi-asset structures.', category: 'Quantitative' },
  { term: 'Autocorrelation', definition: 'Correlation of a time series with its own past values. First-order autocorrelation: serial correlation between consecutive returns. Positive autocorrelation (momentum) in daily/weekly returns; negative autocorrelation (mean reversion) often observed at monthly frequencies.', category: 'Quantitative' },
  { term: 'Cointegration', definition: 'Two non-stationary time series are cointegrated if their linear combination is stationary. The basis of pairs trading: two stocks that move together long-term but diverge short-term. The spread is mean-reverting even though individual prices are random walks.', category: 'Quantitative' },
  { term: 'Hidden Markov Model', definition: 'A statistical model where the system is assumed to be in one of a finite set of hidden states (e.g. bull/bear market regimes). Observations (returns) are generated by each state\'s distribution. Used for regime detection and adaptive strategy design.', category: 'Quantitative' },
  { term: 'Principal Component Analysis', definition: 'Dimensionality reduction technique that extracts orthogonal components explaining the most variance in a dataset. In fixed income, the first three PCs typically explain 99%+ of yield curve variance: parallel shift, twist, and butterfly.', category: 'Quantitative' },
  { term: 'GARCH Model', definition: 'Generalised Autoregressive Conditional Heteroskedasticity — models time-varying volatility where current variance depends on past squared residuals and past variance. Captures volatility clustering (calm periods followed by turbulent periods) observed in financial returns.', category: 'Quantitative' },
  { term: 'Backtest Overfitting', definition: 'The danger of tuning a strategy to historical data such that it performs superbly in-sample but fails out-of-sample. Multiple testing without adjustment inflates apparent Sharpe ratios. The Deflated Sharpe Ratio adjusts for multiple testing in strategy selection.', category: 'Quantitative' },

  // ── Risk Management (extended) ────────────────────────────────────────────
  { term: 'Liquidity-Adjusted VaR', definition: 'VaR modified to account for the bid-ask spread and market impact of liquidating positions under stress. Standard VaR assumes frictionless execution; LaVaR is more realistic for large positions in illiquid markets.', category: 'Risk Management' },
  { term: 'Model Risk', definition: 'The risk of loss from using incorrect or misapplied financial models. Highlighted in the 2012 JPMorgan "London Whale" loss ($6B+) where a flawed CDS index model underestimated portfolio risk. SR 11-7 (Federal Reserve guidance) now requires formal model validation.', category: 'Risk Management' },
  { term: 'Margin Call', definition: 'A broker\'s demand for additional collateral when a margin account falls below the maintenance margin level. Forces leveraged investors to either post more cash or liquidate positions — a key amplifier of financial crises (LTCM 1998, March 2020).', category: 'Risk Management' },
  { term: 'Funding Liquidity Risk', definition: 'The risk that an entity cannot roll over short-term debt or meet margin calls, forcing asset sales at distressed prices. Distinct from market liquidity risk. Banks are particularly vulnerable — asset-liability mismatch amplified the 2008 crisis.', category: 'Risk Management' },
  { term: 'Wrong-Way Risk', definition: 'When credit exposure to a counterparty is positively correlated with the probability of the counterparty defaulting. For example, buying CDS protection from a bank on bank sector debt — the protection is most needed when the protection seller is most likely to fail.', category: 'Risk Management' },
  { term: 'Stress Test', definition: 'Evaluating a portfolio under extreme but plausible scenarios — 2008 financial crisis, pandemic lockdown, 1987 crash. Regulators require banks to run DFAST/CCAR stress tests annually. Scenario design matters more than the statistical model.', category: 'Risk Management' },
  { term: 'Drawdown Duration', definition: 'The length of time a portfolio spends below its previous peak. Even a strategy with high returns may be unacceptable if drawdown duration is long — investors capitulate. The 2000–2002 tech crash took the NASDAQ 15 years to recover its peak.', category: 'Risk Management' },
  { term: 'Tail Dependence', definition: 'The tendency of assets to crash together in extreme events even if their average correlation is low. Standard correlation understates tail risk. Copula models (especially t-copulas) capture tail dependence and are used in CDO pricing and portfolio stress testing.', category: 'Risk Management' },

  // ── Factor Investing (extended) ────────────────────────────────────────────
  { term: 'Size Factor', definition: 'Small-cap stocks have historically outperformed large-cap stocks on a risk-adjusted basis — the Fama-French SMB (Small Minus Big) factor. Explanations include illiquidity premium, neglect, and greater operating leverage. The premium has been smaller post-publication.', category: 'Factor Investing' },
  { term: 'Profitability Factor', definition: 'High gross-profitability firms (gross profit / assets) outperform low-profitability firms. Novy-Marx (2013) showed this is distinct from value. Combined with value, it identifies cheap, profitable companies — the "quality value" combination.', category: 'Factor Investing' },
  { term: 'Investment Factor', definition: 'Conservative-investment firms (low asset growth) outperform aggressive-investment firms. Part of the Fama-French 5-factor model (CMA: Conservative Minus Aggressive). Captures overinvestment destroys value; capital discipline is rewarded.', category: 'Factor Investing' },
  { term: 'Idiosyncratic Momentum', definition: 'Momentum in the residual return of a stock after stripping out factor exposures. Stronger and less prone to crashes than raw price momentum. Requires a factor model to compute and is used in more sophisticated momentum strategies.', category: 'Factor Investing' },
  { term: 'Defensive Factor', definition: 'Low-beta, low-volatility stocks have delivered higher risk-adjusted returns than theory (CAPM) predicts — the "low volatility anomaly." Explanations include leverage constraints causing investors to overpay for high-beta, and institutional career risk leading to herding.', category: 'Factor Investing' },
  { term: 'Factor Timing', definition: 'Dynamically adjusting factor exposures based on valuations, macroeconomic regime, or sentiment signals. Academic evidence is mixed — factor spreads are hard to forecast consistently. Most practitioners use strategic (static) factor allocation rather than tactical timing.', category: 'Factor Investing' },
  { term: 'Factor Zoo', definition: 'The proliferation of 400+ published factors (anomalies) in academic finance literature. Cochrane\'s 2011 AFA Presidential Address coined the term. Most factors don\'t survive multiple testing corrections, transaction cost adjustment, or out-of-sample testing.', category: 'Factor Investing' },

  // ── Macro Finance (extended) ──────────────────────────────────────────────
  { term: 'Secular Stagnation', definition: 'The hypothesis (Summers, 2013) that advanced economies face a persistent shortfall of demand and low neutral interest rates, requiring structural policy responses. Low population growth, rising inequality, and declining capital goods prices suppress investment demand.', category: 'Macro' },
  { term: 'Monetary Transmission Mechanism', definition: 'The process by which central bank policy rates influence the real economy through credit conditions, asset prices, exchange rates, and expectations. Rate hikes work with "long and variable lags" (Friedman) — typically 12–18 months before full effect.', category: 'Macro' },
  { term: 'Capital Account', definition: 'Records cross-border flows of investment and loans. A current account deficit must be financed by a capital account surplus. The U.S. runs large, persistent current account deficits financed by foreign capital inflows (buying Treasuries, equities, real estate).', category: 'Macro' },
  { term: 'Sterilisation', definition: 'When a central bank offsets the domestic money supply effects of foreign exchange intervention. Selling local currency bonds to drain the liquidity created by buying foreign currency. China practiced large-scale sterilised intervention to manage the RMB peg.', category: 'Macro' },
  { term: 'Helicopter Money', definition: 'Direct monetary financing of fiscal stimulus — the central bank credits households\' accounts without a corresponding liability. More stimulative than QE (which is asset-swapping) because it permanently increases the money stock. Discussed seriously for the first time during COVID.', category: 'Macro' },
  { term: 'Nominal GDP Targeting', definition: 'A monetary policy framework where the central bank targets a path for nominal GDP (real GDP + inflation) rather than inflation alone. Proponents argue it better accommodates supply shocks and reduces the zero lower bound problem. Never formally adopted by a major central bank.', category: 'Macro' },
  { term: 'Twin Deficits', definition: 'The simultaneous occurrence of fiscal deficit and current account deficit. Theoretically linked: government borrowing absorbs private savings, forcing the economy to import capital. The U.S. in the 1980s and 2000s illustrated the twin deficits hypothesis.', category: 'Macro' },
  { term: 'Trilemma (Impossible Trinity)', definition: 'A country cannot simultaneously maintain a fixed exchange rate, free capital flows, and independent monetary policy. It can only achieve two of three. Most developed economies choose free capital flows and independent monetary policy, accepting floating currencies.', category: 'Macro' },
  { term: 'Fiscal Multiplier', definition: 'The ratio of output change to the size of a fiscal stimulus. A multiplier above 1.0 means $1 of government spending generates more than $1 of GDP. Multipliers are larger when: monetary policy is at the ZLB, the economy is in a recession, and import leakage is small.', category: 'Macro' },

  // ── Corporate Finance (extended) ───────────────────────────────────────────
  { term: 'Rights Issue', definition: 'A company raises new equity by offering existing shareholders the right to buy additional shares at a discount before offering them to new investors. Dilutive to non-participating shareholders. Used in distressed situations or major capital expansions.', category: 'Corporate Finance' },
  { term: 'Spin-off', definition: 'A corporate action where a subsidiary is separated from the parent company and becomes an independent publicly traded company. Shareholders receive shares in the new entity. Often creates value by allowing each business to be valued and managed independently.', category: 'Corporate Finance' },
  { term: 'Carve-Out', definition: 'A partial IPO of a subsidiary, retaining a majority ownership stake. Raises capital and establishes a market value for the unit. Different from a spin-off (full separation) and a split-off (exchange offer for parent shares).', category: 'Corporate Finance' },
  { term: 'Earnout', definition: 'A contingent payment in an M&A transaction linked to the acquired company\'s future performance. Bridges valuation gaps between buyer and seller. Disputes over earnout calculations are one of the most litigated aspects of M&A deals.', category: 'Corporate Finance' },
  { term: 'Dividend Recapitalisation', definition: 'A leveraged company takes on new debt specifically to pay a large special dividend to equity owners (usually a private equity sponsor). Criticized as extracting value while increasing financial fragility. Popular in PE-backed companies when credit markets are accommodating.', category: 'Corporate Finance' },
  { term: 'EBITDAR', definition: 'Earnings Before Interest, Taxes, Depreciation, Amortisation, and Rent/Restructuring costs. Used for industries with significant operating lease obligations (airlines, retail) where rent is a core operating expense comparable to D&A. Normalises for lease accounting differences.', category: 'Corporate Finance' },
  { term: 'Accretion/Dilution Analysis', definition: 'Tests whether a proposed acquisition increases (accretive) or decreases (dilutive) the acquirer\'s earnings per share in the first year. A deal that is EPS-accretive is not necessarily value-creating — growth in EPS does not equal growth in intrinsic value.', category: 'Corporate Finance' },
  { term: 'Net Working Capital', definition: 'Current assets minus current liabilities (excluding cash and debt). Represents the capital tied up in the operating cycle. NWC fluctuates with business volume and seasonality. In M&A, a "peg" or target NWC is negotiated so the seller doesn\'t drain cash before closing.', category: 'Corporate Finance' },
  { term: 'Covenant-Lite Loans', definition: 'Leveraged loans with few or no maintenance financial covenants (e.g. leverage ratio tests). Became the norm in private credit during the 2010s low-rate era. Less protection for lenders — violations that would trigger renegotiation in traditional deals go undetected until default.', category: 'Corporate Finance' },
  { term: 'Mezzanine Financing', definition: 'Hybrid debt/equity capital sitting between senior secured debt and common equity in the capital structure. Typically unsecured, higher-yielding, and includes equity kickers (warrants). Common in leveraged buyouts to fill the gap between bank debt and sponsor equity.', category: 'Corporate Finance' },

  // ── Trading & Market Microstructure (extended) ────────────────────────────
  { term: 'Payment for Order Flow', definition: 'A practice where brokers receive compensation from market makers for routing customer orders to them. Controversial because it creates a conflict of interest — the broker may not achieve best execution. Led to SEC scrutiny and debate about market structure reform.', category: 'Trading' },
  { term: 'Dark Pool', definition: 'A private off-exchange trading venue where large institutional orders execute without pre-trade price transparency. Designed to minimize market impact. Critics argue dark pools fragment liquidity and disadvantage retail investors.', category: 'Trading' },
  { term: 'Internalization', definition: 'When a broker-dealer fills customer orders from its own inventory rather than routing to an exchange. Legal and common, but creates potential conflict of interest if the firm\'s desk profits from the spread rather than seeking best execution.', category: 'Trading' },
  { term: 'Limit Order Book', definition: 'The queue of all resting limit orders on an exchange at each price level. Market depth is visible (for lit markets). High-frequency traders derive signals from order book dynamics — changes in bid-ask depth, order flow imbalance, and queue position.', category: 'Trading' },
  { term: 'Execution Algorithm', definition: 'Software that breaks large orders into smaller pieces to minimize market impact. Common types: TWAP (time-weighted average price), VWAP (volume-weighted average price), Implementation Shortfall (minimise slippage vs. decision price). Standard tools for institutional trading.', category: 'Trading' },
  { term: 'Slippage', definition: 'The difference between the expected execution price and the actual fill price. Caused by market impact (price moves against a large order), latency, or insufficient liquidity. In backtests, slippage assumptions dramatically affect strategy performance.', category: 'Trading' },
  { term: 'T+1 Settlement', definition: 'U.S. equities moved to T+1 (next business day) settlement in 2024, from T+2. Reduces counterparty and settlement risk, frees margin capital, but requires faster reconciliation. The SEC mandated the change partly in response to the 2021 GameStop settlement stress.', category: 'Trading' },
  { term: 'Opening Auction', definition: 'A batch process at market open where all buy and sell orders at or near the opening price are matched simultaneously. Produces the official opening price. Institutional investors often use the opening auction to establish or exit positions with reduced market impact.', category: 'Trading' },

  // ── Hedge Fund Strategies (extended) ─────────────────────────────────────
  { term: 'Global Macro', definition: 'A strategy that takes directional positions in currencies, rates, commodities, and equity indices based on macroeconomic analysis. Managers like Soros (1992 GBP crisis) and Druckenmiller express high-conviction theses through leveraged liquid instruments.', category: 'Hedge Funds' },
  { term: 'Managed Futures', definition: 'Also called Commodity Trading Advisors (CTAs) — systematic trend-following strategies trading futures across asset classes. Historically provides crisis alpha (performed well in 2008 and 2022) due to short-selling capability and momentum orientation.', category: 'Hedge Funds' },
  { term: 'Event-Driven', definition: 'Strategies targeting corporate events: mergers, spinoffs, earnings announcements, restructurings, index additions. Sub-strategies include merger arbitrage, activist investing, distressed debt, and special situations. Return profile is more equity-like than macro strategies.', category: 'Hedge Funds' },
  { term: 'Relative Value', definition: 'Strategies that exploit pricing discrepancies between related instruments — convertible arb, fixed income relative value, vol arb — while remaining market-neutral. Returns depend on convergence of the spread rather than market direction. Sensitive to liquidity crises that widen spreads.', category: 'Hedge Funds' },
  { term: 'Quantitative Equity Long/Short', definition: 'Systematic strategies that go long and short baskets of stocks based on factor signals (value, momentum, quality). Market-neutral versions aim for zero net beta. Factor crowding is a key risk — when many quants own the same names, an unwind is disorderly.', category: 'Hedge Funds' },
  { term: 'Multi-Strategy Fund', definition: 'A hedge fund running multiple independent strategy "pods" — macro, L/S equity, credit, vol. Capital is dynamically allocated to pods. Two Sigma, Millennium, and Citadel are largest examples. Provides diversification but high fixed costs require elevated AUM.', category: 'Hedge Funds' },
  { term: 'Side Pocket', definition: 'A segregated account within a hedge fund for illiquid positions. Prevents liquid investors from being redeemed ahead of illiquid ones. Became controversial in 2008 when some managers moved assets into side pockets to avoid forced selling.', category: 'Hedge Funds' },
  { term: 'High-Water Mark', definition: 'The historical peak net asset value of a hedge fund. Performance fees are only charged on gains above the high-water mark. Protects investors from paying fees twice on the same return. Managers below their HWM often shut down rather than work for free.', category: 'Hedge Funds' },

  // ── Private Capital (extended) ─────────────────────────────────────────────
  { term: 'Fund of Funds', definition: 'An investment vehicle that allocates to multiple underlying private equity or hedge funds rather than directly to companies or securities. Provides diversification and access to closed funds, but adds a second layer of fees (typically 1%+5%).', category: 'Private Capital' },
  { term: 'Secondary Market (PE)', definition: 'The buying and selling of existing LP interests in private equity funds. Buyers (secondaries firms) acquire interests at a discount; sellers get liquidity before fund termination. The secondaries market has grown to ~$130B annually, improving PE liquidity.', category: 'Private Capital' },
  { term: 'GP-Led Secondary', definition: 'A fund manager (GP) creates a continuation vehicle to transfer select high-quality assets from an expiring fund, giving existing LPs liquidity or the option to roll into the new vehicle. Controversial for conflicts of interest but provides a path to hold winners longer.', category: 'Private Capital' },
  { term: 'Unitranche Debt', definition: 'A single-tranche loan that blends first-lien and second-lien pricing into one instrument. Simpler for borrowers (one lender relationship) and common in direct lending. The "first out / last out" structure lets parts of the unitranche be bought by different investors.', category: 'Private Capital' },
  { term: 'Platform Investment', definition: 'A private equity "buy-and-build" strategy where an initial (platform) company acquisition is followed by smaller bolt-on acquisitions in the same sector. Creates multiple arbitrage (buying bolt-ons at lower multiples, benefiting from the platform\'s premium multiple at exit).', category: 'Private Capital' },
  { term: 'NAV Loan', definition: 'A loan secured against the net asset value of a private equity fund\'s portfolio. Allows GPs to provide liquidity to LPs, fund add-on investments, or extend fund life without a costly secondary sale. Borrowing against an illiquid portfolio — a source of systemic risk concern.', category: 'Private Capital' },
  { term: 'Capital Call Line', definition: 'A short-term revolving credit facility secured by uncalled LP commitments. Allows PE funds to make investments before calling capital, improving IRR by delaying the clock start. Critics argue subscription lines can inflate reported IRRs by 1–3 percentage points.', category: 'Private Capital' },

  // ── Accounting & Financial Statements (extended) ──────────────────────────
  { term: 'Deferred Revenue', definition: 'Payments received before the associated service or product is delivered. A liability on the balance sheet — the company owes the customer. SaaS companies convert deferred revenue to recognized revenue as subscriptions are fulfilled. Growing deferred revenue signals strong pre-sales demand.', category: 'Accounting' },
  { term: 'Capitalization vs. Expensing', definition: 'Capitalizing an expenditure spreads the cost over its useful life (PP&E, intangibles), boosting near-term earnings. Expensing recognizes the full cost immediately, hitting earnings harder upfront. Aggressive capitalization can mask deteriorating economics.', category: 'Accounting' },
  { term: 'Goodwill Impairment', definition: 'When the carrying value of goodwill (the premium paid over fair value in an acquisition) exceeds its implied fair value, the excess must be written down. Goodwill impairment is non-cash but signals the acquisition has underperformed original expectations.', category: 'Accounting' },
  { term: 'Days Sales Outstanding', definition: 'DSO = (accounts receivable / revenue) × days in period. Measures how quickly a company collects payment. Rising DSO can signal aggressive revenue recognition, customer credit deterioration, or collection problems. Compare to historical trends and industry peers.', category: 'Accounting' },
  { term: 'Days Payable Outstanding', definition: 'DPO = (accounts payable / COGS) × days. Measures how long a company takes to pay suppliers. High DPO can mean the company has negotiating power or is stretching payables. Abnormally high DPO may signal liquidity stress.', category: 'Accounting' },
  { term: 'Inventory Turnover', definition: 'COGS / average inventory. Measures how efficiently a company manages inventory. High turnover = lean inventory management (just-in-time). Low turnover = slow-moving or obsolete inventory. Declining turnover can signal demand softening or over-buying.', category: 'Accounting' },
  { term: 'Cash Conversion Cycle', definition: 'DIO + DSO − DPO. Measures the time from cash outflow (purchasing inventory) to cash inflow (collecting from customers). A negative CCC (Amazon, Costco) means the company collects cash before paying suppliers — extremely capital-efficient.', category: 'Accounting' },
  { term: 'Revenue Recognition (ASC 606)', definition: 'The five-step framework for recognizing revenue: identify contract, identify performance obligations, determine transaction price, allocate price to obligations, recognize revenue when obligations are satisfied. ASC 606 created consistent standards across industries.', category: 'Accounting' },
  { term: 'Normalized Earnings', definition: 'Reported earnings adjusted to remove non-recurring items — restructuring charges, impairments, legal settlements, stock-based compensation (sometimes). Used for valuation multiples to avoid distortion from one-time events. Analysts debate which adjustments are legitimate.', category: 'Accounting' },
  { term: 'Off-Balance-Sheet Financing', definition: 'Financial obligations not recorded on the balance sheet — operating leases (pre-IFRS 16), Special Purpose Entities, certain derivatives. IFRS 16 / ASC 842 brought most operating leases on-balance-sheet. Enron\'s SPE abuse made off-balance-sheet structures a regulatory priority.', category: 'Accounting' },

  // ── Behavioral Finance (extended) ─────────────────────────────────────────
  { term: 'Mental Accounting', definition: 'Thaler\'s theory that people assign money to separate mental "accounts" (income, savings, entertainment) with different spending rules. Leads to irrational decisions — spending a tax rebate freely while refusing to sell a loss-making stock in the "investment" account.', category: 'Behavioral Finance' },
  { term: 'Herding', definition: 'When investors abandon independent analysis and follow the crowd. Rational herding can occur when private information is sparse and observing others\' actions is informative. Irrational herding amplifies bubbles and crashes. Documented in mutual fund manager behaviour and analyst recommendations.', category: 'Behavioral Finance' },
  { term: 'Status Quo Bias', definition: 'The tendency to prefer the current state of affairs over alternatives, even when changing would improve outcomes. In investing: holding concentrated employer stock, keeping a suboptimal asset allocation, or failing to rebalance. Default options (in 401k design) powerfully exploit status quo bias.', category: 'Behavioral Finance' },
  { term: 'Narrative Economics', definition: 'Shiller\'s theory that viral stories and economic narratives drive economic behaviour and asset prices — sometimes more powerfully than fundamentals. The 1990s "new economy" narrative and the 2020s AI narrative shaped capital allocation and valuations beyond what earnings justified.', category: 'Behavioral Finance' },
  { term: 'Regret Aversion', definition: 'The tendency to avoid decisions that could lead to regret — either of action (losing after buying) or inaction (missing a rally after not buying). Leads to holding losers too long (postponing realizing the regret of selling at a loss) and selling winners too early.', category: 'Behavioral Finance' },
  { term: 'Recency Bias', definition: 'Overweighting recent events in predictions about the future. Investors extrapolate recent returns — buying at market tops and selling at bottoms. Post-2008, retail investors under-allocated to equities for years due to recency-driven fear.', category: 'Behavioral Finance' },
  { term: 'Gambler\'s Fallacy', definition: 'The erroneous belief that past random events affect future probabilities of independent events. In investing: assuming a stock is "due" to rally after several down days, or expecting mean reversion in truly random processes. Distinct from actual mean-reverting financial phenomena.', category: 'Behavioral Finance' },

  // ── Technical Analysis (extended) ─────────────────────────────────────────
  { term: 'Golden Cross', definition: 'When the 50-day moving average crosses above the 200-day moving average — a bullish trend signal. The opposite (50-day crossing below 200-day) is the "Death Cross," a bearish signal. Widely followed in retail and some institutional momentum strategies.', category: 'Technical Analysis' },
  { term: 'Fibonacci Retracement', definition: 'Price levels based on Fibonacci ratios (23.6%, 38.2%, 50%, 61.8%, 78.6%) applied to significant price swings. Traders use these as potential support/resistance levels. The mathematical basis (Fibonacci sequence) has no proven causal link to markets but remains popular as a self-fulfilling tool.', category: 'Technical Analysis' },
  { term: 'Relative Strength Index', definition: 'RSI — a momentum oscillator ranging 0–100 measuring speed and magnitude of price changes. Readings above 70 are traditionally "overbought"; below 30 are "oversold." Divergence between RSI and price (price making new highs while RSI falls) is a potential reversal signal.', category: 'Technical Analysis' },
  { term: 'MACD', definition: 'Moving Average Convergence Divergence — the difference between a 12-period and 26-period exponential moving average. A signal line (9-period EMA of MACD) generates buy/sell signals at crossovers. One of the most widely used technical indicators in trend-following systems.', category: 'Technical Analysis' },
  { term: 'Bollinger Bands', definition: 'A volatility envelope: a middle band (20-period SMA) and upper/lower bands set at ±2 standard deviations. Prices touching the upper band may be overbought; lower band oversold. "Band squeeze" (narrowing bands) signals a potential breakout — direction undetermined.', category: 'Technical Analysis' },
  { term: 'Head and Shoulders', definition: 'A chart pattern with three peaks — a higher central peak (head) flanked by two lower peaks (shoulders). Breaking the "neckline" (connecting the two troughs) is a bearish reversal signal. The measured move target = head height minus neckline.', category: 'Technical Analysis' },
  { term: 'Volume Profile', definition: 'A histogram of trading volume at each price level over a defined period. High-volume nodes represent price levels with strong past support/resistance. Used by institutions to identify "value areas" and plan execution around high-volume price anchors.', category: 'Technical Analysis' },
  { term: 'Elliott Wave Theory', definition: 'Ralph Nelson Elliott\'s theory that markets move in predictable 5-wave impulse structures (3 up, 2 corrective) followed by 3-wave corrections. Disputed by academics (subjective, unfalsifiable), but influences technical traders and provides a framework for sentiment cycles.', category: 'Technical Analysis' },

  // ── Commodities (extended) ─────────────────────────────────────────────────
  { term: 'Convenience Yield', definition: 'The implicit benefit of physically holding a commodity versus a futures contract — e.g., the option to use it in production or avoid supply disruptions. When convenience yield is high, spot prices exceed discounted futures prices (backwardation). Highest during supply squeezes.', category: 'Commodities' },
  { term: 'Crude Differentials', definition: 'The price spread between different crude oil benchmarks — WTI vs. Brent, Brent vs. Dubai, sour vs. sweet crude. Differentials reflect transportation costs, refinery configurations, and regional supply/demand dynamics. Vital for refiners\' margin calculations.', category: 'Commodities' },
  { term: 'OPEC+ Production Cuts', definition: 'Coordinated output reductions by OPEC and allied non-OPEC producers (notably Russia). Aim to support oil prices by reducing supply. Market impact depends on compliance, exemptions for distressed members, and demand trajectory. Saudi Arabia often acts as swing producer.', category: 'Commodities' },
  { term: 'Commodity Supercycle', definition: 'A multi-decade period of rising real commodity prices driven by structural demand growth (industrialisation of China 2000–2010) outstripping supply. Supply response lags due to long capital investment cycles. Supercycle end is marked by massive capex, oversupply, and falling prices.', category: 'Commodities' },
  { term: 'Crack Spread', definition: 'The price differential between crude oil and refined petroleum products (gasoline, diesel). Measures refinery profitability. A 3-2-1 crack spread: 3 barrels crude → 2 gasoline + 1 diesel. Refiners hedge this spread using futures to lock in margins.', category: 'Commodities' },
  { term: 'Henry Hub', definition: 'The physical natural gas pricing point in Louisiana that serves as the benchmark for NYMEX gas futures and North American gas contracts. All gas prices in the region are quoted as a premium or discount to Henry Hub. Named for the pipeline interchange in Erath, Louisiana.', category: 'Commodities' },
  { term: 'Precious Metals Spread', definition: 'The gold/silver ratio — how many ounces of silver to buy one ounce of gold. Historically ranges 40–80x; extremes signal relative value opportunities. The copper/gold ratio is used as a macro indicator — rising copper relative to gold signals economic expansion.', category: 'Commodities' },

  // ── Digital Assets (extended) ──────────────────────────────────────────────
  { term: 'Proof of Stake', definition: 'A blockchain consensus mechanism where validators are chosen based on their staked cryptocurrency rather than computational work (Proof of Work). Ethereum switched to PoS in "The Merge" (2022), reducing energy consumption by ~99%. Validators earn staking yield but risk slashing for misbehaviour.', category: 'Digital Assets' },
  { term: 'Layer 2 Scaling', definition: 'Secondary networks built on top of a base blockchain (Layer 1) to increase transaction throughput and reduce fees. Ethereum L2s (Arbitrum, Optimism, zkSync) settle batches of transactions on mainnet, inheriting its security while offering 10–100x cheaper transactions.', category: 'Digital Assets' },
  { term: 'Impermanent Loss', definition: 'The temporary loss experienced by liquidity providers in AMMs when the price ratio of their deposited assets changes from when they deposited. If the price diverges significantly, the LP would have been better off simply holding. The loss is "impermanent" because it reverses if prices return.', category: 'Digital Assets' },
  { term: 'MEV', definition: 'Maximal Extractable Value — profit captured by block producers (miners/validators) by reordering, inserting, or censoring transactions within a block. Includes front-running, sandwich attacks, and arbitrage. Estimated at billions per year in Ethereum; a major research and fairness concern.', category: 'Digital Assets' },
  { term: 'CBDC', definition: 'Central Bank Digital Currency — a digital form of sovereign currency issued directly by a central bank. Distinct from cryptocurrency (no decentralization) and stablecoins (legal tender, zero credit risk). Over 130 countries are exploring CBDCs; China\'s e-CNY is the largest live pilot.', category: 'Digital Assets' },
  { term: 'Crypto Basis Trade', definition: 'Going long spot Bitcoin/ETH while shorting futures to capture the premium (basis) between futures and spot prices. The basis arises from leveraged long demand in perpetual futures. Similar to cash-and-carry arbitrage in commodities. Carry trade for crypto market structure.', category: 'Digital Assets' },
  { term: 'Tokenization of Real Assets', definition: 'Representing ownership of real-world assets (real estate, bonds, private equity) as blockchain tokens. Promises fractional ownership, 24/7 settlement, and programmable compliance. BlackRock\'s BUIDL fund ($500M+) is the largest tokenized treasury fund to date.', category: 'Digital Assets' },

  // ── Real Estate Finance (extended) ────────────────────────────────────────
  { term: 'Loan-to-Value Ratio', definition: 'LTV = loan amount / property appraised value. The primary risk metric in mortgage underwriting. Higher LTV = more leverage = greater default risk. GSEs (Fannie Mae, Freddie Mac) typically require LTV ≤80% or private mortgage insurance above 80%.', category: 'Real Estate' },
  { term: 'Debt Service Coverage Ratio', definition: 'DSCR = net operating income / total debt service. Lenders require DSCR ≥1.2–1.25x for commercial real estate loans. Below 1.0 means the property\'s income doesn\'t cover debt payments. A key underwriting metric for CRE and infrastructure lending.', category: 'Real Estate' },
  { term: 'Rent Roll', definition: 'A schedule of all tenant leases in a property: tenant name, leased area, rent per square foot, lease start/end dates, and options. The fundamental document for underwriting commercial real estate cash flows. Investors analyze weighted average lease expiry (WALE) for income stability.', category: 'Real Estate' },
  { term: 'NOI', definition: 'Net Operating Income — gross rental income minus operating expenses (property taxes, insurance, maintenance), excluding debt service and capital expenditures. The primary valuation metric for income-producing real estate. Cap rate = NOI / property value.', category: 'Real Estate' },
  { term: 'Vacancy Rate', definition: 'The percentage of available units or space that is unoccupied. A key supply/demand indicator for property markets. Structural vacancy (long-term, due to oversupply or changing demand) is more destructive to NOI than cyclical vacancy.', category: 'Real Estate' },
  { term: 'CMBS', definition: 'Commercial Mortgage-Backed Securities — securitised pools of commercial real estate loans (office, retail, hotel, industrial). Tranched by risk: investment-grade senior tranches have priority claims; junior B-pieces absorb first losses. A $1T+ market in the U.S.', category: 'Real Estate' },
  { term: 'Triple Net Lease', definition: 'A lease structure where the tenant pays base rent plus all property expenses: property taxes, insurance, and maintenance. Most favorable to landlords (predictable cash flow, no surprises). Common for single-tenant retail (McDonald\'s, Walgreens) and net lease REITs (STORE Capital, NNN).', category: 'Real Estate' },

  // ── Banking & Credit (extended) ───────────────────────────────────────────
  { term: 'Net Interest Margin', definition: 'NIM = (interest income − interest expense) / average earning assets. The spread a bank earns on its loan and investment portfolio over funding costs. The core profitability metric for banks. Compressed by low rates and flat yield curves; expands during rate hiking cycles.', category: 'Banking' },
  { term: 'Tier 1 Capital Ratio', definition: 'Core equity capital (common equity + retained earnings) divided by risk-weighted assets. The primary regulatory capital adequacy measure. Basel III requires 6% minimum; U.S. GSIBs typically run 12%+. Below-minimum triggers dividend restrictions and regulatory scrutiny.', category: 'Banking' },
  { term: 'Credit Default Swap', definition: 'A bilateral contract where the buyer pays a periodic premium (spread) in exchange for compensation if a reference entity defaults. The CDS spread reflects the market\'s implied default probability. The AIG bailout (2008) was triggered by $440B of credit protection sold via CDS.', category: 'Banking' },
  { term: 'Loan Loss Reserve', definition: 'An accounting provision against expected credit losses in a bank\'s loan portfolio. CECL (Current Expected Credit Loss) accounting requires banks to estimate lifetime expected losses on day one of origination, smoothing the credit cycle — a change from the previous incurred loss model.', category: 'Banking' },
  { term: 'Leverage Ratio (Banking)', definition: 'Tier 1 capital divided by total leverage exposure (on- and off-balance-sheet). The supplementary leverage ratio (SLR) applies to the largest U.S. banks. Unlike the risk-weighted capital ratio, it treats all assets equally — provides a backstop against risk model gaming.', category: 'Banking' },
  { term: 'Covered Bond', definition: 'A bond backed by a pool of high-quality assets (typically mortgages or public sector loans) that remain on the issuer\'s balance sheet. Dual recourse: bondholders can claim against both the issuer and the cover pool. More senior than ABS; used heavily by European bank funding.', category: 'Banking' },
  { term: 'Bail-In', definition: 'A resolution mechanism where a failing bank\'s creditors (subordinated bondholders, sometimes senior creditors) absorb losses rather than taxpayers (bailout). Required under BRRD in Europe and OLA in the U.S. for G-SIBs. Introduced as a reform post-2008 to end "too big to fail."', category: 'Banking' },
  { term: 'Correspondent Banking', definition: 'A relationship where one bank provides services on behalf of another, typically for cross-border transactions in a currency neither bank natively holds. De-risking (correspondent banks exiting relationships) due to AML compliance costs has reduced financial inclusion in developing countries.', category: 'Banking' },

  // ── Insurance & Structured Products ──────────────────────────────────────
  { term: 'Duration Gap', definition: 'The mismatch between the average duration of assets and liabilities in an insurance company or pension fund. A positive gap means assets are longer-dated than liabilities — rising rates hurt asset values more than they reduce liability values. Managing the gap is the core of ALM.', category: 'Banking' },
  { term: 'CDO', definition: 'Collateralised Debt Obligation — a structured product that pools credit assets and issues tranched securities. Cash flow CDOs hold bonds/loans; synthetic CDOs use CDS contracts. Mis-rated CDOs backed by subprime mortgages were at the center of the 2008 financial crisis.', category: 'Banking' },
  { term: 'CLO', definition: 'Collateralised Loan Obligation — a CDO backed specifically by leveraged loans. The largest segment of the U.S. structured finance market (~$1T). AAA tranches are bought by banks and insurers; equity tranches by PE sponsors. CLO managers actively trade the underlying loan portfolio.', category: 'Banking' },
  { term: 'ABS', definition: 'Asset-Backed Security — securitised pools of receivables: auto loans, credit cards, student loans, equipment leases. Payments flow through a waterfall structure from senior to junior tranches. ABS issuance reached $300B+ annually in the U.S., diversifying bank funding and investor opportunities.', category: 'Banking' },

  // ── Economic Indicators (extended) ────────────────────────────────────────
  { term: 'Beige Book', definition: 'The Federal Reserve\'s informal report on current economic conditions in each of the 12 Fed districts, compiled from business contacts, economists, and advisory councils. Published 8 times a year, two weeks before each FOMC meeting. Provides colour on labour markets, prices, and activity.', category: 'Economic Indicators' },
  { term: 'CAPE Ratio', definition: 'Cyclically Adjusted P/E Ratio (Shiller P/E) — the S&P 500 price divided by 10-year average inflation-adjusted earnings. Smooths business cycle effects. CAPE above 30 has historically preceded below-average 10-year returns. Currently one of the most-cited equity valuation metrics.', category: 'Economic Indicators' },
  { term: 'Retail Sales', definition: 'Monthly survey of sales at retail establishments — a direct measure of consumer spending (70% of U.S. GDP). Released early each month; often market-moving. Core retail sales (ex-auto, ex-gas) give a cleaner read on underlying consumer demand and real GDP tracking.', category: 'Economic Indicators' },
  { term: 'Producer Price Index', definition: 'PPI measures the average change in prices received by domestic producers for goods and services. A leading indicator for CPI — input cost increases eventually pass through to consumer prices. "Pipeline inflation" tracked via PPI components (finished goods, intermediate goods, raw materials).', category: 'Economic Indicators' },
  { term: 'Durable Goods Orders', definition: 'Monthly measure of orders for manufactured items expected to last 3+ years (aircraft, machinery, appliances). Core capex proxy: non-defence capital goods orders ex-aircraft (a.k.a. "core capex") is the best leading indicator of business investment spending.', category: 'Economic Indicators' },
  { term: 'Initial Jobless Claims', definition: 'Weekly count of new unemployment insurance applications — the highest-frequency leading indicator of the labour market. Rises sharply in recessions. Sustained claims above 300K historically signal deteriorating labour conditions. Markets react to surprises relative to 4-week moving average.', category: 'Economic Indicators' },

  // ── International Finance (extended) ──────────────────────────────────────
  { term: 'Purchasing Power Parity', definition: 'The theory that exchange rates should equalize the price of identical goods across countries. The Big Mac Index (The Economist) is a light-hearted PPP gauge. In practice, non-tradeable goods and barriers cause persistent deviations. PPP exchange rates are used to compare real GDPs across countries.', category: 'International Finance' },
  { term: 'Capital Flight', definition: 'The rapid outflow of financial and physical assets from a country due to political risk, currency risk, or economic instability. Self-reinforcing: outflows weaken the currency, create inflation, and fuel further flight. Argentina, Venezuela, and Turkey experienced episodes in the 2010s-2020s.', category: 'International Finance' },
  { term: 'Sovereign Wealth Fund', definition: 'A state-owned investment fund managing excess foreign exchange reserves or commodity revenues. Norway\'s Government Pension Fund ($1.7T), Abu Dhabi Investment Authority ($993B), and GIC ($770B) are the largest. Long investment horizons and low liquidity needs make SWFs patient capital providers.', category: 'International Finance' },
  { term: 'Balance of Payments Crisis', definition: 'Occurs when a country cannot finance its current account deficit or service foreign debt, forcing devaluation or IMF assistance. Typically preceded by fixed exchange rate overvaluation, excessive short-term foreign debt, or reserve depletion. Asia 1997, Argentina 2001, Sri Lanka 2022.', category: 'International Finance' },
  { term: 'Carry Trade', definition: 'Borrowing in a low-interest-rate currency and investing in a high-interest-rate currency to earn the rate differential. Vulnerable to "sudden stop" reversals when risk sentiment shifts — the "carry trade unwind" can trigger sharp moves in EM currencies and risk assets.', category: 'International Finance' },
  { term: 'Eurobond', definition: 'A bond issued and traded outside the domestic market of the currency in which it is denominated. A USD Eurobond issued by a German company in London is not subject to U.S. disclosure requirements. The Eurobond market is a primary source of cross-border sovereign and corporate debt financing.', category: 'International Finance' },

  // ── Credit Markets ─────────────────────────────────────────────────────────
  { term: 'Investment Grade', definition: 'Corporate bonds rated BBB-/Baa3 or above by S&P/Moody\'s. These ratings signify low default risk. IG bonds trade at tighter spreads than high yield. Institutional mandates (insurance, pension funds) restrict them to IG — a large, price-insensitive buyer base.', category: 'Fixed Income' },
  { term: 'High-Yield Spread', definition: 'The yield difference between a high-yield (junk) bond index and comparable maturity Treasuries. A key credit market health indicator — spreads widen in recessions and risk-off episodes, tighten in benign environments. Historically, spreads above 800bps signal elevated recession risk.', category: 'Fixed Income' },
  { term: 'Credit Cycle', definition: 'The recurring expansion and contraction of credit availability. During expansion: lending standards loosen, leverage rises, spreads compress. During contraction: default rates spike, lending standards tighten, spreads widen. Credit cycles lag equity cycles and can independently amplify recessions.', category: 'Fixed Income' },
  { term: 'Distressed Debt', definition: 'Bonds or loans trading at significant discounts (often defined as yield spread > 1,000bps) due to elevated default probability. Distressed investors buy at deep discounts hoping to recover more than the purchase price through restructuring, bankruptcy, or operational turnaround.', category: 'Fixed Income' },
  { term: 'Payment-in-Kind', definition: 'PIK — a debt instrument where interest is paid by issuing additional debt rather than cash. Common in LBOs and distressed situations where cash flows are insufficient. Compounds the outstanding principal, increasing leverage over time. A red flag for credit quality.', category: 'Fixed Income' },

  // ── Regulation & Market Structure ─────────────────────────────────────────
  { term: 'Dodd-Frank Act', definition: 'U.S. financial reform legislation passed in 2010 in response to the 2008 crisis. Key provisions: Volcker Rule (restricts proprietary trading by banks), mandatory central clearing of standardized derivatives, OFR systemic risk monitoring, and FSOC oversight of non-bank SIFIs.', category: 'Banking' },
  { term: 'Basel III', definition: 'International banking regulations strengthening capital requirements, liquidity standards (LCR, NSFR), and leverage ratios post-2008. Full implementation (Basel III "endgame") is expected in the late 2020s and has been contested by U.S. banks due to capital surcharges on trading books.', category: 'Banking' },
  { term: 'Volcker Rule', definition: 'Section 619 of Dodd-Frank prohibiting federally insured banks from engaging in proprietary trading or owning/investing in hedge funds and private equity funds. Designed to reduce speculative risk-taking with insured deposits. Implementation has been contentious due to difficulty distinguishing prop trading from market-making.', category: 'Banking' },
  { term: 'RegNMS', definition: 'Regulation National Market System — SEC rules requiring brokers to route orders to the venue offering the best price (Order Protection Rule). Created fragmented markets with 16+ U.S. equity exchanges. Has been criticized for enabling payment-for-order-flow and HFT front-running.', category: 'Trading' },
  { term: 'MiFID II', definition: 'Markets in Financial Instruments Directive II — EU regulation requiring best execution, transparency in trading, and unbundling of research from trading commissions. Research unbundling reduced European sell-side research budgets significantly and contributed to research consolidation.', category: 'Trading' },
  { term: 'Regulation FD', definition: 'Regulation Fair Disclosure — SEC rule requiring public companies to disclose material information simultaneously to all investors rather than selectively to favored analysts. Passed in 2000. Led to the end of selective "guidance" and a shift to public earnings calls and investor days.', category: 'Trading' },
  { term: 'Short-Swing Profit Rule', definition: 'Section 16(b) of the Securities Exchange Act — corporate insiders (officers, directors, >10% shareholders) must disgorge profits from buying and selling the same company\'s stock within a 6-month period. Prevents insiders from profiting on short-term price movements using inside information.', category: 'Trading' },

  // ── Rates & Monetary Policy ────────────────────────────────────────────────
  { term: 'Neutral Rate', definition: 'The theoretical policy rate that neither stimulates nor restrains the economy — also called r* (r-star). When the actual rate is below neutral, monetary policy is accommodative; above neutral, it is restrictive. Unobservable; estimated from economic models and inferred from Fed communications.', category: 'Macro' },
  { term: 'Quantitative Tightening', definition: 'The reverse of QE — the central bank shrinks its balance sheet by not reinvesting maturing bonds (passive QT) or actively selling securities. Reduces bank reserves and should put upward pressure on long-term yields and tighten financial conditions. The Fed began QT in 2022.', category: 'Macro' },
  { term: 'SOFR', definition: 'Secured Overnight Financing Rate — the benchmark rate replacing LIBOR for USD contracts, based on overnight repo transactions secured by U.S. Treasuries. LIBOR transition completed in June 2023. SOFR is backward-looking and harder to use in forward-looking loan pricing (Term SOFR fills the gap).', category: 'Fixed Income' },
  { term: 'Federal Funds Rate', definition: 'The target interest rate set by the FOMC at which banks lend reserves to each other overnight. The primary lever of U.S. monetary policy. Changes in the Fed funds rate ripple through mortgages, corporate lending, and global USD-denominated markets.', category: 'Macro' },
  { term: 'Dot Plot', definition: 'The FOMC\'s "Summary of Economic Projections" showing each member\'s anonymous estimate of appropriate future interest rates. Released quarterly. Markets parse the dot plot to anticipate rate path changes — a key tool of Fed forward guidance since 2012.', category: 'Macro' },
  { term: 'Reverse Repo Facility', definition: 'The Fed\'s overnight reverse repurchase facility allows money market funds and GSEs to park excess cash at the Fed in exchange for Treasuries. Used to set a floor under short-term rates. RRP usage exceeded $2.5T in 2022–23 as money flooded into safe assets post-QE.', category: 'Macro' },
  { term: 'Yield Curve Control', definition: 'A monetary policy tool where the central bank targets a specific yield on a particular maturity bond, buying unlimited amounts to defend the target. Japan has used YCC since 2016; Australia adopted it briefly in 2020. Requires commitment to unlimited bond purchases.', category: 'Macro' },

  // ── Equity Markets ─────────────────────────────────────────────────────────
  { term: 'Share Buyback', definition: 'A corporation repurchases its own shares in the open market or via tender offer, reducing shares outstanding. Increases EPS mechanically and returns cash to shareholders tax-efficiently. Buybacks are more flexible than dividends and can signal management confidence in undervaluation.', category: 'Corporate Finance' },
  { term: 'Dual-Class Shares', definition: 'A share structure where different classes have different voting rights. Founders (Google, Meta, Snap) retain control via 10:1 super-voting shares while raising capital from public investors with limited votes. Controversial for governance — shareholders bear risk without proportionate control.', category: 'Corporate Finance' },
  { term: 'IPO Lock-Up', definition: 'A contractual restriction preventing insiders (founders, employees, early investors) from selling shares for typically 90–180 days after an IPO. Lock-up expiry often creates selling pressure. SPAC mergers and direct listings have been used partly to avoid traditional lock-up constraints.', category: 'Corporate Finance' },
  { term: 'SPAC', definition: 'Special Purpose Acquisition Company — a blank-check shell company that raises capital in an IPO with the intention of merging with a private company. Offers a faster, more certain path to public markets than a traditional IPO. SPAC volume surged in 2020–21 before collapsing due to poor post-merger performance.', category: 'Corporate Finance' },
  { term: 'Short Interest', definition: 'The total number of shares sold short divided by float (% short interest) or daily volume (days to cover). High short interest can indicate bearish sentiment or signal a potential short squeeze. Rising short interest while a stock rallies creates the conditions for a squeeze.', category: 'Trading' },
  { term: 'Market Capitalisation', definition: 'The total market value of a company\'s outstanding shares: price × shares outstanding. Used to classify companies as large-cap (>$10B), mid-cap ($2–$10B), or small-cap (<$2B). Market cap, not share price, determines a company\'s size and index inclusion weight.', category: 'Valuation' },
  { term: 'Price-to-Sales Ratio', definition: 'Market cap divided by annual revenue. Used to value high-growth companies with no earnings. More stable than P/E (earnings can be negative) but ignores profitability. Technology sector PSR ratios compressed dramatically from 2021 peaks as rates rose and profitability was rewarded.', category: 'Valuation' },
  { term: 'Earnings Revision Momentum', definition: 'The trend in analyst EPS estimate revisions — upgrades versus downgrades. Stocks with rising revisions tend to outperform (positive surprise momentum). Used as a quality/momentum signal in systematic strategies. Reflects fundamental improvement faster than backward-looking value metrics.', category: 'Factor Investing' },
  { term: 'Dividend Discount Model', definition: 'Intrinsic value = sum of all future dividends discounted to present value. Simple DDM uses the Gordon Growth Model for stable growers; multi-stage DDM captures growth phases. Requires reliable dividend forecasts — most appropriate for mature, predictable dividend payers.', category: 'Valuation' },
  { term: 'Earnings Power Value', definition: 'Bruce Greenwald\'s concept: the value of a company assuming current earnings persist forever (a no-growth perpetuity). EPV = normalized EBIT × (1 − tax rate) / WACC. Any premium above EPV must be justified by verifiable growth prospects — a conservative valuation floor.', category: 'Valuation' },
  { term: 'Franchise Value', definition: 'The portion of a company\'s value attributable to its ability to earn above its cost of capital over time. Franchise value = total intrinsic value − asset value. Companies with durable competitive advantages (moats) have high franchise value; commodity producers have near-zero franchise value.', category: 'Valuation' },
  { term: 'Earnings Quality', definition: 'The degree to which reported earnings are a true reflection of the company\'s underlying economic performance. High-quality earnings: cash-backed, recurring, conservatively accounted. Red flags: rising accruals, aggressive revenue recognition, non-cash gains, or frequent "one-time" charges.', category: 'Accounting' },
  { term: 'Accrual Anomaly', definition: 'The empirical finding that companies with high accruals (earnings less supported by cash flow) tend to underperform, while low-accrual companies outperform. Published by Sloan (1996). Part of the quality factor and widely incorporated in quantitative equity strategies.', category: 'Factor Investing' },
  { term: 'Float', definition: 'The portion of a company\'s shares available for trading by the public — total shares minus insider holdings, lockups, and restricted shares. Low-float stocks are more volatile and subject to short squeezes. Index inclusion requires minimum float thresholds.', category: 'Trading' },
  { term: 'Block Trade', definition: 'A large privately negotiated securities transaction, typically 10,000+ shares or $200,000+ in value. Often executed off-exchange to minimize market impact. Investment banks facilitate "block crosses" by finding natural counterparties. Significant blocks are often disclosed via SEC Form 4.', category: 'Trading' },
  { term: 'Risk-Free Rate', definition: 'The theoretical return on an investment with zero default risk, used as the baseline in asset pricing models. Typically proxied by short-term U.S. Treasury bill yields (or long-term Treasuries for matching DCF duration). The risk-free rate is the foundation of CAPM and DCF discounting.', category: 'Portfolio Theory' },
  { term: 'Equity Risk Premium', definition: 'The excess return investors expect from equities over the risk-free rate to compensate for higher risk. Historical ERP (U.S.): ~5–6% annually. Implied ERP (based on current valuation) fluctuates with market prices. Higher ERP = cheaper stocks; lower ERP = more expensive. A key input to WACC.', category: 'Portfolio Theory' },
  { term: 'Home Bias', definition: 'The tendency of investors to overweight domestic assets relative to a globally optimal allocation. Documented across all countries — even despite clear diversification benefits from international stocks. Attributed to familiarity, currency risk aversion, transaction costs, and regulatory constraints.', category: 'Behavioral Finance' },
  { term: 'Disposition Effect', definition: 'The behavioural tendency to sell winners too quickly (to lock in gains) and hold losers too long (to avoid realising losses). First documented by Shefrin and Statman (1985). Creates the momentum anomaly — losers continue losing; winners continue winning, partly because investors sell them too early.', category: 'Behavioral Finance' },
  { term: 'Adaptive Markets Hypothesis', definition: 'Andrew Lo\'s framework positing that market efficiency is not static but evolves as participants adapt to changing conditions. Markets can be intermittently inefficient — strategies that work in one regime fail in another. Reconciles EMH and behavioral finance anomalies within an evolutionary framework.', category: 'Behavioral Finance' },
  { term: 'Flight to Quality', definition: 'During market stress, investors shift from risky assets (equities, high yield, EM) into safe havens (Treasuries, gold, JPY, USD). Compresses Treasury yields and tightens spreads between safe and risky assets. A classic crisis pattern observed in 2008, 2020, and 2022 rate shock episodes.', category: 'Macro' },
  { term: 'Negative Screening', definition: 'An ESG investment approach that excludes certain sectors or companies (tobacco, weapons, gambling) from a portfolio. The oldest form of socially responsible investing. Limited impact on returns (small exclusion sets) but does not require engagement with underlying companies.', category: 'ESG' },
  { term: 'Green Bond', definition: 'Fixed income instruments where proceeds are earmarked for environmental projects — renewable energy, energy efficiency, clean transportation. Certified by the Climate Bonds Initiative or aligned with ICMA Green Bond Principles. Issuance exceeded $500B annually by 2021.', category: 'ESG' },
  { term: 'Impact Investing', definition: 'Investments made with the explicit intention of generating positive social or environmental outcomes alongside financial returns. Ranges from market-rate (concessional returns accepted for impact) to purely commercial (additionality + market returns). GIIN estimates $1.2T in global impact assets under management.', category: 'ESG' },
  { term: 'Stewardship', definition: 'Active ownership: using shareholder rights (voting proxies, engaging management) to improve corporate governance and long-term value. Institutionalised by the UK Stewardship Code and PRI. BlackRock, Vanguard, and State Street voting decisions attract enormous attention as they own ~20% of S&P 500 companies.', category: 'ESG' },

  // ── Final Additions ────────────────────────────────────────────────────────
  { term: 'Market Microstructure', definition: 'The study of how trading rules, order flow, information, and market design affect transaction costs and price discovery. Key topics: bid-ask spread decomposition, price impact models, adverse selection, and optimal execution. Pioneered by Glosten, Milgrom, and Kyle in the 1980s.', category: 'Trading' },
  { term: 'Adverse Selection', definition: 'In market microstructure, the risk that a market maker is trading against an informed counterparty who knows more about the security\'s true value. Market makers widen spreads to protect against adverse selection. Kyle\'s lambda quantifies how much prices move per unit of order flow.', category: 'Trading' },
  { term: 'Earnings Per Share', definition: 'Net income attributable to common shareholders divided by weighted average diluted shares outstanding. The most cited per-share profitability metric. Basic EPS uses actual shares; diluted EPS includes the dilutive effect of options, warrants, and convertible securities.', category: 'Accounting' },
  { term: 'Free Cash Flow Yield', definition: 'Free cash flow per share divided by stock price — the FCF equivalent of earnings yield. Valued by fundamental investors as a more reliable signal than EPS-based yield because FCF is harder to manipulate. High FCF yield suggests the stock is cheap relative to cash generation.', category: 'Valuation' },
  { term: 'Terminal Value', definition: 'The value of a business beyond the explicit forecast period in a DCF model — typically 70–80% of the total enterprise value. Calculated as either a perpetuity (Gordon Growth) or exit multiple. Terminal value dominates DCF results, making the long-run growth and discount rate assumptions critical.', category: 'Valuation' },
  { term: 'Margin of Safety', definition: 'Benjamin Graham\'s principle: only buy when the market price is significantly below intrinsic value, providing a cushion against errors in the valuation. A 30–50% discount is typical. The margin of safety protects against imprecise estimates and unforeseen adverse developments.', category: 'Valuation' },
  { term: 'Credit Spread Widening', definition: 'When the yield premium demanded by investors to hold corporate bonds over risk-free government bonds increases. Signals deteriorating credit conditions, recession risk, or flight to safety. Spread widening also tightens financial conditions by raising corporate borrowing costs.', category: 'Fixed Income' },
  { term: 'Dividend Payout Ratio', definition: 'Dividends per share divided by EPS — the proportion of earnings returned to shareholders as dividends. A high payout ratio limits reinvestment capacity. Investors watch the payout ratio to assess dividend sustainability — ratios above 75–80% can be unsustainable during earnings downturns.', category: 'Corporate Finance' },
  { term: 'Asset Allocation', definition: 'The process of dividing an investment portfolio among different asset classes (equities, fixed income, alternatives, cash) to balance risk and return. The single most important determinant of long-run portfolio performance. Strategic asset allocation sets the long-run target; tactical shifts are shorter-term.', category: 'Portfolio Theory' },
];

export async function GET() {
  // Deterministic rotation: one new term per calendar day
  const dayOfYear = Math.floor(
    (Date.now() - new Date(new Date().getFullYear(), 0, 0).getTime()) / 86_400_000
  );
  const term = TERMS[dayOfYear % TERMS.length];
  return NextResponse.json(term);
}
